window.DEEP = {"ar.law.defs":{"k":"نظام التعليم العام","t":"التعريفات والمراحل (المادة 1)","body":[],"pts":["**المعلم**: من **يُرخَّص له** بالعمل في مهنة التعليم العام.","**البرنامج**: نشاط داخل المنهج لهدف محدد؛ و**المقرر**: المحتوى الذي تتضمنه الخطة ويدرسه الطلاب."],"traps":[],"src":"نظام التعليم العام، المادة 1"},"ar.law.general":{"k":"نظام التعليم العام","t":"أحكام عامة يكثر السؤال عنها","body":["مواد قصيرة في النظام تتكرر في الأسئلة لأنها تحسم مواقف يومية في المدرسة."],"pts":["للوزارة تكليف معلمي الحكومي **بتدريس مقررات خارج تخصصهم** وفق قواعد يقرها المجلس (المادة 46).","**الأسرة شريك**: الوزارة تضع ضوابط تمكّن أولياء الأمور من المشاركة في تحقيق أهداف التعليم (المادة 50)."],"traps":[],"src":"نظام التعليم العام، المواد 5 و 6 و 24 و 46 و 50 و 67"},"ar.law.effective":{"k":"نظام التعليم العام","t":"الصدور والنشر والنفاذ","body":[],"pts":["قرار مجلس الوزراء بالموافقة: **رقم 103 وتاريخ 1448/1/22هـ**.","يلغي النظام **كل ما يتعارض معه** (المادة 68)، وألغى القرار وثائق محددة [[مع فترة انتقالية|ar.law.repeal]]."],"traps":[],"src":"نظام التعليم العام، المادة 68؛ قرار مجلس الوزراء رقم 103 (1448/1/22هـ)؛ المرسوم الملكي م/36 (1448/1/27هـ)"},"ar.law.repeal":{"k":"نظام التعليم العام","t":"ما ألغاه قرار الموافقة على النظام","body":["قرار مجلس الوزراء 103 ألغى وثائق محددة مع **استمرار العمل بأحكامها** حتى يقر **مجلس شؤون التعليم العام** البديل **خلال سنة من نفاذ النظام**."],"pts":["**لائحة تنظيم المدارس الأهلية** (1395هـ) و**لائحة المدارس الأجنبية** (1418هـ).","ضوابط إحداث مدارس التعليم العام، وضوابط تعيين مديري المدارس الأهلية، وضوابط مدارس تحفيظ القرآن الصيفية، وأحكام مدارس الثغر النموذجية.","و**نظام تعليم الكبار ومحو الأمية** (م/22 وتاريخ 1392/6/9هـ) بالشرط الانتقالي نفسه."],"traps":[],"src":"قرار مجلس الوزراء رقم 103 وتاريخ 1448/1/22هـ، البنود 3–5 (أم القرى)"},"ar.law.council":{"k":"نظام التعليم العام","t":"مجلس شؤون التعليم العام","body":["مجلس ينشئه النظام **برئاسة وزير التعليم**، ونائبه **نائب الوزير للتعليم العام**."],"pts":["أعضاؤه نواب وزراء (منهم المالية والصحة والموارد البشرية)، و**رئيس هيئة تقويم التعليم والتدريب**، و**4 مختصين** يعيَّنون 3 سنوات (المادة 7).","من اختصاصه: الخطط والسياسات، و**تحديد سن القبول**، وشروط التعاقد مع المعلمين، ولوائح الخاص وذوي الإعاقة والموهوبين ورياض الأطفال (المادة 8).","**التقويم الدراسي**: الوزارة تعدّه، والمجلس يرفعه موصياً، ومجلس الوزراء يعتمده (المادة 8).","يجتمع **كل 90 يوماً على الأقل**، والنصاب **ثلثا الأعضاء** (المادة 9).","و**الوزارة** هي الجهة المشرفة على التعليم العام (المادة 13)."],"traps":["رئيس المجلس **وزير التعليم**؛ رئيس هيئة تقويم التعليم والتدريب **عضو**."],"src":"نظام التعليم العام، المواد 7–9؛ قرار مجلس الوزراء رقم 103، البند 2؛ سياسة التعليم، المادة 231"},"ar.law.goals":{"k":"نظام التعليم العام","t":"أهداف النظام (المادة 2)","body":["الهدف: **الجودة وحسن الأداء**، وبناء الطلاب **دينياً ووطنياً وقيمياً وعلمياً وثقافياً ومهارياً**، عبر اثني عشر هدفاً."],"pts":["العقيدة الإسلامية، والولاء لولاة الأمر والانتماء للوطن و**الأسرة نواة المجتمع**، و**الهوية الوطنية**.","**إتقان العربية**، وقيم **التسامح والتعايش** وحقوق الإنسان.","**التحصن من التيارات المنحرفة** و**التعامل الواعي مع المحتوى الإعلامي**، و**التفكير الإبداعي والناقد**.","**التعلم مدى الحياة**، والبحث والابتكار و**التقنيات الناشئة**، والعمل التطوعي والصحة والسلامة.","**لغة أجنبية واحدة على الأقل** (الهدف 12)، وكانت السياسة تقول «لغة أخرى من اللغات الحية على الأقل» (م 50 منها)."],"traps":["الهدف 12 «لغة أجنبية واحدة **على الأقل**»، لا «لغتان» ولا «الإنجليزية تحديداً»."],"src":"نظام التعليم العام، المادة 2؛ سياسة التعليم، المادة 50"},"ar.law.compulsory":{"k":"نظام التعليم العام","t":"الحق والمجانية والإلزام (المادتان 3 و 4)","body":[],"pts":["**سن القبول** واقتراح تعديل **حدّي الإلزام** من اختصاص **المجلس** (المادة 8)."],"ex":["طالب في الحادية عشرة انقطع لأن والده يشغّله في متجره. هو في سن الإلزام، فتتخذ الوزارة الإجراءات النظامية تجاه من تسبب في انقطاعه بالتنسيق مع الجهات المختصة (المادة 4/2)."],"traps":[],"src":"نظام التعليم العام، المواد 3 و 4 و 8؛ سياسة التعليم، المادة 121"},"ar.law.inclusion":{"k":"نظام التعليم العام","t":"الكشف المبكر ودمج ذوي الإعاقة (المواد 19–21)","body":["ثلاث درجات: **كشف مبكر** عن اضطرابات النمو أو السلوك، ثم **دمج** ذوي الإعاقة في المؤسسات التعليمية، ثم **برامج ومراكز متخصصة** لمن يتعذر دمجه."],"pts":["لمن يتعذر دمجه: برامج ومراكز متخصصة، وبرامج **رقمية وعن بُعد** (المادة 21).","لوائح ذوي الإعاقة والموهوبين يقرها **المجلس** (المادة 8)."],"ex":["طالب ضعيف بصر في فصل عادي: يبقى مدموجاً، وتُوفَّر له تقنيات مساعدة، ويُقوَّم بأساليب تراعي قدراته (المادة 20)."],"traps":[],"src":"نظام التعليم العام، المواد 8 و 19–21؛ سياسة التعليم، المادة 188"},"ar.law.gifted":{"k":"نظام التعليم العام","t":"الموهوبون والتسريع (المادتان 22 و 23)","body":["رعاية الموهوبين **باقية** من السياسة (م 57 و 192–194 منها)، والنظام يفصّلها ويضيف **ضوابط التسريع**."],"pts":["برامج **بفصول أو مدارس مخصصة**، و**مراكز إثرائية**، و**معايير واضحة** لتحديدهم، وتدريب المعلمين، وشراكات مع الجامعات (المادة 22).","ومن واجب المعلم **اكتشاف الموهوبين والمبدعين** (المادة 49/2)."],"traps":[],"src":"نظام التعليم العام، المواد 22 و 23 و 49؛ سياسة التعليم، المواد 57 و 192–194"},"ar.law.curriculum":{"k":"نظام التعليم العام","t":"المناهج والاختبارات الوطنية والاعتماد (المواد 27–30)","body":["ثلاث جهات: **المركز الوطني للمناهج** و**الوزارة** و**هيئة تقويم التعليم والتدريب**."],"pts":["**الإطار الوطني لمناهج التعليم العام**: تعدّه الوزارة والهيئة مع المركز الوطني للمناهج (المادة 27).","**الكتب الدراسية دون مقابل** لمن يطبق المنهج الحكومي (المادة 29).","المؤسسات تطبق **الاختبارات والمقاييس الوطنية والدولية** التي تنفذها الهيئة (المادة 30/1).","الخاص يلتزم **بالاعتماد المدرسي** من الهيئة أو هيئة دولية **تعتمدها الهيئة** (المادة 30/2)."],"traps":["الإطار الوطني للمناهج عمل **مشترك** بين ثلاث جهات، لا تنفرد به الوزارة."],"src":"نظام التعليم العام، المواد 27–30"},"ar.law.license":{"k":"نظام التعليم العام","t":"المؤسسات التعليمية الخاصة: الترخيص والرسوم (المواد 31–36)","body":["الترخيص **اختصاص الوزارة**، والقطاع الخاص يشمل **المستثمر الأجنبي** والقطاع غير الربحي. وكانت السياسة لا تسمح بترخيص المدارس الأهلية **لغير السعوديين** (م 176 منها)."],"pts":["قرار الوزارة **كتابي خلال 30 يوماً**، والرفض **مسبَّب** مع **حق التظلم** (المادة 32).","لا يجوز **قبل موافقة الوزارة**: فتح المؤسسة، أو نقل ملكيتها، أو تغيير **اسمها أو موقعها أو مرحلتها** (المادة 33).","الالتزام **بتدريس مواد الهوية الوطنية** التي يعتمدها المركز الوطني للمناهج (المادة 31).","الرسوم: الوزارة تضع **معايير تعديلها** ويعتمدها **المجلس**، والمؤسسة تحدد رسومها وفقها (المادة 35)."],"traps":["مهلة الرد على الترخيص **30 يوماً**، لا 60 (التظلم من الجزاء) ولا 90 (اجتماع المجلس)."],"src":"نظام التعليم العام، المواد 31–36؛ سياسة التعليم، المادة 176"},"ar.law.srights":{"k":"نظام التعليم العام","t":"حقوق الطالب وواجباته (المادة 38)","body":["للطالب، إضافة إلى حقوقه في الأنظمة الأخرى والاتفاقيات الدولية، **سبعة حقوق**، وعليه **خمسة التزامات**."],"pts":["(أ) بيئة تمكّنه من التحصيل. (ب) بيئة **آمنة نفسياً وجسدياً وفكرياً** وحمايته من **جميع أشكال الإيذاء**.","(ج) **سماع شكواه وقيدها واتخاذ الإجراء** حيالها. (د) **ألا يُكلَّف بعمل ناتج عن اجتهاد فردي** يخالف النظام واللوائح.","(هـ) **الرعاية الصحية الأولية**. (و) **جوائز وحوافز** عند تميزه. (ز) **تسلّم شهادة النجاح دون قيد أو شرط**.","الالتزامات: الاحترام، والحضور في الوقت، وبذل الجهد، **وعدم الإضرار بالمدرسة**، و**قواعد السلوك والمواظبة**."],"ex":[],"traps":[],"src":"نظام التعليم العام، المادة 38"},"ar.law.teacher":{"k":"نظام التعليم العام","t":"حقوق المعلم وواجباته (المادتان 48 و 49)","body":[],"pts":["حقوقه في الحكومي: بيئة مناسبة، و**التدريب والتطوير المهني**، وفرص الإسهام في تطوير التعليم، وجوائز وحوافز (المادة 48).","التدريس **وفق الأهداف والبرامج المعتمدة** (المادة 49/1).","مراعاة **الفروق الفردية** و**أعلى مستويات العدالة** واكتشاف الموهوبين (المادة 49/2).","[[القدوة الحسنة والالتزام بالميثاق|ar.law.ethics]] (المادة 49/3)، واستثمار اليوم الدراسي (49/4)، والإسهام في التطوير المهني والبحوث (49/5)."],"traps":[],"src":"نظام التعليم العام، المادتان 48 و 49؛ سياسة التعليم، المواد 163–172"},"ar.law.ethics":{"k":"نظام التعليم العام","t":"القدوة وميثاق أخلاقيات مهنة التعليم (المادة 49/3)","body":["من واجبات المعلم: **تمثيل القدوة الحسنة** خُلقاً، و**الالتزام بقيم الهوية الوطنية**، و**الابتعاد عن كل ما يمس شرف المهنة داخل المدرسة وخارجها**، و**الالتزام بميثاق أخلاقيات مهنة التعليم**.","بذلك صار الالتزام بالميثاق **نصاً في نظام** صادر بمرسوم ملكي (يُعمل به بعد نفاذ النظام)، لا توجيهاً إدارياً فقط."],"pts":["عبارة **«داخل المدرسة وخارجها»** تُدخل سلوك المعلم العام، ومنه حضوره الرقمي، في واجب القدوة."],"ex":["معلم ينشر في حسابه الشخصي محتوى ساخراً يمس زملاءه وطلابه ويقول: «هذا خارج الدوام». المادة 49/3 تجعل القدوة واجباً **داخل المدرسة وخارجها**."],"traps":[],"src":"نظام التعليم العام، المادة 49 (الفقرة 3)"},"ar.law.penalties":{"k":"نظام التعليم العام","t":"المخالفات والجزاءات (المواد 57–64)","body":["النظام يطبق على المعلمين والإداريين في الحكومي إجراءات **نظام الانضباط الوظيفي** عبر **لجنة المادة 62**، ويضع جزاءات بحسب الجسامة."],"pts":["**تدابير عاجلة** عند **قرائن** الإخلال بالنظام العام أو اللحمة الوطنية: منع من العمل داخل المؤسسة، أو **كف اليد مؤقتاً**؛ يتخذها الوزير أو من يفوضه (المادة 58).","بعد **الثبوت**: غير الجسيمة = أي جزاء عدا إنهاء الخدمة (ويجوز عند **التكرار**)؛ الجسيمة = **إنهاء الخدمة والمنع من العودة للتعليم العام والخاص** (المادة 59).","المدرسة الخاصة: إنذار، إيقاف تسجيل، **غرامة 5,000–50,000 ريال**، إلغاء الترخيص مع إكمال العام **على نفقة المالك** (المادة 60).","اللجنة **3 أعضاء على الأقل** (المادة 62)، والتظلم أمام **الجهة القضائية خلال 60 يوماً** (المادة 63)."],"traps":[],"src":"نظام التعليم العام، المواد 57–64"},"ar.law.report":{"k":"نظام التعليم العام","t":"واجب الإبلاغ عن الاعتداء والإيذاء (المادة 65)","body":[],"pts":["الغرض: **استكمال الإجراءات النظامية** لدى الجهة المختصة، لا إنهاء الموضوع داخلياً."],"ex":["مشاجرة عنيفة أمام بوابة المدرسة بعد الانصراف أُصيب فيها طالب: المادة 65 تشمل **محيط المؤسسة**، فتبلغ الإدارة الجهة المختصة ولا تكتفي بالصلح."],"traps":["الاكتفاء بالصلح أو بإبلاغ ولي الأمر لا يحقق الإبلاغ إلى **الجهة المختصة**."],"src":"نظام التعليم العام، المادة 65"},"ar.l05.mainidea":{"k":"استيعاب المقروء","t":["Main Idea","الفكرة الرئيسة والعنوان"],"body":["طريقة عملية: اسأل «عمّ يتحدث النص كله؟» ثم «ماذا يقول عنه؟»."],"pts":[],"ex":[],"traps":[],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 4.1: استيعاب المقروء","aka":["الفكرة الرئيسة","العنوان المناسب"]},"ar.l07.maturation":{"k":"مبادئ النمو","t":["Maturation, Learning & Readiness","النضج والتعلم والاستعداد"],"body":[],"pts":["المشي يعتمد على النضج أساساً، والقراءة على النضج والتعلم معاً."],"ex":[],"traps":[],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1؛ أدبيات علم نفس النمو","aka":["النضج","الاستعداد"]},"ar.l07.havighurst":{"k":"النظريات","t":["Havighurst — Developmental Tasks","هافجهرست: مطالب النمو"],"body":["لكل مرحلة عمرية **مطالب نمو**: مهام ينبغي إتقانها في وقتها، تنشأ من النضج وتوقعات المجتمع وقيم الفرد؛ إنجازها يقود إلى النجاح في المطالب التالية، والإخفاق يصعّبها. وهو صاحب فكرة **اللحظة القابلة للتعلم**."],"pts":["المراهقة: تقبل الجسم، والاستقلال الانفعالي عن الوالدين، واختيار مهنة والاستعداد لها."],"traps":[],"src":"Havighurst, Developmental Tasks and Education؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1","aka":["هافجهرست","مطالب النمو"]},"ar.l07.piaget":{"k":"النظريات","t":["Piaget — Cognitive Development","بياجيه: مراحل النمو المعرفي"],"body":[],"pts":["درس **المفاهيم الأساسية** (الزمن، المكان، العدد، السببية)؛ والتطبيق: **تعليم يناسب مرحلة النمو**، وطالب **المتوسطة والثانوية** تناسبه المناقشة والفروض.","تجربة الكرات الخشبية: طفل ما قبل العمليات لا يدرك **علاقة الجزء بالكل** (تضمين الفئات)؛ و**العمليات المحسوسة/المادية (7–11)** و**العمليات المجردة/الصورية (11 فأكثر)**."],"ex":[],"traps":[],"src":"Piaget & Inhelder, The Psychology of the Child؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1","aka":["بياجيه","مراحل بياجيه","النمو المعرفي","التمركز حول الذات"]},"ar.l07.conservation":{"k":"بياجيه","t":["Conservation vs. Object Permanence","الاحتفاظ ودوام الشيء"],"body":[],"pts":["يُكتسب الاحتفاظ تدريجياً: العدد أولاً، ثم الكتلة والسائل، ثم الوزن، ثم الحجم آخرها.","غياب الاحتفاظ سببه التمركز على بُعد واحد (الطول دون العرض)."],"ex":["تُباعد أزرار أحد صفين متساويين فيقول طالب الصف الثاني «ما زالت 7»: احتفاظ العدد."],"traps":[],"src":"Piaget & Inhelder, The Psychology of the Child","aka":["الاحتفاظ","دوام الشيء","المعكوسية"]},"ar.l07.erikson":{"k":"النظريات","t":["Erikson — Psychosocial Development","إريكسون: النمو النفسي الاجتماعي"],"body":["ويركز على الأنا والمجتمع بدل الدوافع الجنسية، ويمد النمو طوال العمر."],"pts":["**الثقة مقابل عدم الثقة (0–1)** ← **الاستقلال مقابل الخجل والشك (1–3)** ← **المبادرة مقابل الذنب (3–6)**.","**الألفة مقابل العزلة** ← **الإنتاجية مقابل الركود** ← **التكامل مقابل اليأس**."],"ex":[],"traps":[],"src":"Erikson, Childhood and Society؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1","aka":["إريكسون","الاجتهاد مقابل الدونية","الهوية مقابل تشتت الهوية"]},"ar.l07.kohlberg":{"k":"النظريات","t":["Kohlberg — Moral Development","كولبرج: مراحل النمو الأخلاقي"],"body":[],"pts":["مناقشة المعضلات ترفع مستوى التبرير."],"traps":[],"src":"Kohlberg, Essays on Moral Development؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1","aka":["كولبرج","المعضلة الأخلاقية"],"ex":["لماذا لا نغش؟ «لأن الغش ظلم لمن اجتهد» (مبدأ العدل)."]},"ar.l07.freud":{"k":"النظريات","t":["Freud — Psychosexual Stages","فرويد: المراحل النفسية الجنسية"],"body":["سيجموند فرويد مؤسس التحليل النفسي: الشخصية تتشكل مبكراً عبر مراحل نفسية جنسية، وتتكون من **الهو** (اللذة) و**الأنا** (الواقع، المنظم) و**الأنا الأعلى** (الضمير)."],"pts":["الفمية (0–1) ← الشرجية (1–3) ← القضيبية (3–6) ← **الكمون (6–12)** ← التناسلية."],"traps":[],"src":"Freud, Three Essays on the Theory of Sexuality","aka":["فرويد","مرحلة الكمون","الأنا الأعلى"]},"ar.l07.abuse":{"k":"الحماية","t":["Abuse & Neglect — Reporting","الإيذاء والإهمال: إجراء الإبلاغ"],"body":[],"pts":["إحالة إلى **لجنة التوجيه الطلابي** لتقدير الخطورة (شديدة/متوسطة/بسيطة) ومستوى الخدمة (عاجلة/غير عاجلة)، ثم محضر رسمي واستدعاء ولي الأمر (ويُراعى اختيار الطالب لشخص مناسب إذا كان ولي الأمر هو المتسبب)."],"traps":[],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ، المادة 29","aka":["الإيذاء","الإهمال","مركز البلاغات"]},"ar.l08.gardner":{"k":"النظريات","t":["Gardner — Multiple Intelligences","جاردنر: الذكاءات المتعددة"],"body":["هوارد جاردنر رفض أن يكون الذكاء قدرة واحدة يقيسها اختبار واحد، ورأى أنه **أنواع مستقلة نسبياً** (ثمانية بعد إضافة الطبيعي)، يملك كل طالب خليطاً منها بدرجات مختلفة؛ فينوّع المعلم مداخل الدرس."],"pts":["لغوي، منطقي رياضي، مكاني (بصري)، جسمي حركي، موسيقي.","**اجتماعي (بين شخصي)**: فهم الآخرين؛ **ذاتي (ضمن شخصي)**: فهم الذات والتأمل.","**طبيعي**: تصنيف الكائنات والظواهر الطبيعية."],"ex":[],"traps":[],"src":"Gardner, Frames of Mind؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.2","aka":["جاردنر","الذكاءات المتعددة","الذكاء الذاتي","الذكاء الاجتماعي"]},"ar.l08.ld":{"k":"الفئات الخاصة","t":["Learning Disabilities","صعوبات التعلم"],"body":["ويحدد الدليل التنظيمي للتربية الخاصة الأهلية بـ**تباين واضح بين قدرات الطالب وتحصيله** في جانب أكاديمي (كالقراءة والكتابة والعد والاستدلال الرياضي) أو اضطراب في عملية نفسية، و**ألا تكون ناتجة** عن عوق عقلي أو اضطراب سلوكي أو أسباب حسية أو ظروف التعلم أو الرعاية الأسرية."],"pts":[],"traps":[],"src":"الدليل التنظيمي للتربية الخاصة (وزارة التعليم)، أهلية ذوي صعوبات التعلم","aka":["صعوبات التعلم","محك التباين","محك الاستبعاد","بطء التعلم","التأخر الدراسي"]},"ar.l08.id":{"k":"الفئات الخاصة","t":["Intellectual Disability","الإعاقة الفكرية"],"body":["ويحدد الدليل التنظيمي للتربية الخاصة الأهلية بألا تزيد درجة الذكاء على **75 على مقياس وكسلر أو 69 على ستانفورد بينيه (الصورة الخامسة)** أو ما يعادلهما، مع **قصور في مجالين على الأقل** من المهارات التكيفية."],"pts":["التدريس: أهداف وظيفية وخطوات صغيرة وتكرار وتعزيز فوري."],"traps":[],"src":"الدليل التنظيمي للتربية الخاصة (وزارة التعليم)، أهلية ذوي العوق العقلي","aka":["الإعاقة الفكرية","الإعاقة العقلية","السلوك التكيفي"]},"ar.l08.autism":{"k":"الفئات الخاصة","t":["Autism Spectrum Disorder","اضطراب طيف التوحد"],"body":["ويوزع الدليل التنظيمي الخدمات بالشدة: البسيط يُدمج في مدارس التعليم العام مع **غرفة المصادر**، وما لا يمكن دمجه في الصف العام يُخدم في **فصول خاصة ملحقة** بمدارس التعليم العام، والمتوسط والشديد المصاحب لإعاقات أخرى في **مراكز التوحد ومعاهد التربية الفكرية**."],"pts":["تعليمات قصيرة من خطوة واحدة، وتنبيه مسبق قبل أي تغيير.","أفضل أسلوب لترتيب بيئته **التعلم المنظم** (TEACCH)."],"traps":[],"src":"الدليل التنظيمي للتربية الخاصة (وزارة التعليم)، أهلية ذوي اضطراب طيف التوحد","aka":["التوحد","اضطراب طيف التوحد","التعلم المنظم"]},"ar.l08.iep":{"k":"التربية الخاصة","t":["Assessment & the IEP","التشخيص والخطة التربوية الفردية"],"body":[],"pts":["التشخيص **بعد موافقة ولي الأمر خطياً**، ويرد ولي الأمر خلال مدة لا تتجاوز **14 يوماً** من الإشعار الخطي.","**عدم الاكتفاء بنتائج مقياس واحد**، وحفظ سرية المعلومات، والملاحظة عند الحاجة لمدة فصل دراسي كامل."],"ex":[],"traps":[],"src":"الدليل التنظيمي للتربية الخاصة (وزارة التعليم)، القياس والتشخيص","aka":["الخطة التربوية الفردية","الإحالة","لجنة الخطط التعليمية"]},"ar.l08.inclusion":{"k":"التربية الخاصة","t":["Inclusion & Universal Access","الدمج والبيئة الأقل تقييداً والمواءمات"],"body":["ويحدد **دليل الوصول الشامل 1444** أساليب تعديل المنهج: الحجم، والوقت، والمدخل، والمخرج، وصعوبة المفهوم، والدعم، والتوقعات، والمنهج البديل."],"pts":["**مواءمات الاختبار**: تغيير آلية التطبيق دون تغيير بنيته (مكان منفرد، خط عريض، وقت إضافي).","**تعديلات الاختبار**: تغيير بنيته نفسها (تبسيط الأسئلة، شروح إضافية، آلة حاسبة)."],"traps":["المواءمة تغير طريقة التطبيق، والتعديل يغير الاختبار."],"src":"دليل ومعايير الوصول الشامل لذوي الإعاقة في المنشآت التعليمية 1444هـ؛ الدليل التنظيمي للتربية الخاصة (وزارة التعليم)","aka":["الدمج","البيئة الأقل تقييداً","الوصول الشامل","غرفة المصادر"]},"ar.l08.gifted":{"k":"الموهوبون","t":["Gifted Students — 1447 Rules","الموهوبون: التعريف وفصولهم"],"body":["تعرّف **القواعد التنظيمية لفصول ومدارس الموهوبين 1447هـ** الموهوبين بأنهم من لديهم **استعدادات وقدرات فوق عادية أو أداء متميز عن أقرانهم** في مجال أو أكثر يقدره المجتمع، ويحتاجون رعاية لا يوفرها المنهج العادي. وتعرّف **الإثراء** بخبرات متنوعة متعمقة لا يوفرها المنهج، و**التلمذة** بتواصل الموهوب مع متخصصين وخبراء."],"pts":["فصول الموهوبين **عامة** (إشراف إدارة التعليم) أو **تخصصية** (مع جهة مشاركة).","الفصل من 15 إلى 20 طالباً، ويُغلق إذا قل عن 12 طالباً لسنتين متتاليتين.","القبول باجتياز **مقاييس معتمدة** مع **أكثر من أداة** (سجل المنجزات، المقابلة، استمارات الترشيح، توصية المعلم)."],"traps":[],"src":"القواعد التنظيمية لفصول ومدارس الموهوبين 1447هـ (المواد 1، 4، 5، 9)","aka":["الموهبة","الموهوب","الإثراء","التلمذة"]},"ar.l08.renzulli":{"k":"الموهوبون","t":["Renzulli & Gagné","مفهوم الموهبة: رنزولي وجانييه"],"body":[],"pts":["الالتزام بالمهمة عنصر دافعي: مثابرة طويلة في مجال يحبه."],"traps":["جانييه هنا فرانسوا صاحب نموذج الموهبة، لا روبرت صاحب شروط التعلم."],"src":"Renzulli, The Three-Ring Conception of Giftedness؛ Gagné, DMGT","aka":["رنزولي","الحلقات الثلاث","جانييه","التفوق"]},"ar.l08.accel":{"k":"الموهوبون","t":["Acceleration","التسريع (التعجيل)"],"body":["ويطبقه **الدليل التنظيمي لنظام التسريع** في المرحلتين الابتدائية والمتوسطة."],"pts":["مرتان في المسيرة: من **الرابع إلى السادس الابتدائي**، ومن **الأول إلى الثالث المتوسط**.","الترشيح: درجة القطع في مقياس موهبة، و**97% فأكثر في كل مادة**، و**98% معدلاً عاماً** في المتوسطة، وموافقة ولي الأمر والطالب.","اجتياز اختبار التسريع: **75%** معدلاً عاماً و**50%** في كل مادة."],"traps":[],"src":"الدليل التنظيمي لنظام التسريع (وزارة التعليم)، البنود 1-6 و 1-9","aka":["التسريع","التعجيل","ضغط المنهج"]},"ar.l08.diff":{"k":"التدريس","t":["Tomlinson — Differentiated Instruction","التعليم المتمايز"],"body":[],"pts":["أدواته: المهام المتدرجة، والمراكز، وعقود التعلم، وخيارات المنتج."],"ex":[],"traps":[],"src":"Tomlinson, The Differentiated Classroom؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.2","aka":["التعليم المتمايز","المجموعات المرنة"]},"ar.l09.skinner":{"k":"السلوكية","t":["Skinner — Operant Conditioning","سكنر: الإشراط الإجرائي"],"body":[],"pts":["**تعزيز سالب**: إزالة منفّر فيزيد السلوك (إعفاء من واجب لمن أنجز)."],"traps":[],"src":"Skinner, Science and Human Behavior؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.3","aka":["سكنر","الإشراط الإجرائي","التعزيز السالب","العقاب السالب","التشكيل","مبدأ بريماك"]},"ar.l09.bandura":{"k":"التعلم الاجتماعي","t":["Bandura — Observational Learning","باندورا: التعلم بالملاحظة"],"body":[],"pts":["النماذج: حية، ورمزية (فيديو، قصة)، ولفظية."],"ex":["طالب يرى زميله يُكرَّم لأنه أعاد محفظة وجدها فيزداد حرصه على الأمانة: تعزيز بديل."],"traps":[],"src":"Bandura, Social Foundations of Thought and Action","aka":["باندورا","النمذجة","التعزيز البديل","الحتمية التبادلية"]},"ar.l09.gestalt":{"k":"المعرفية","t":["Gestalt — Insight","الجشطلت والاستبصار"],"body":["أسس **فرتهايمر** الجشطلت مع كوفكا وكوهلر، وشعارها: الكل أكبر من مجموع أجزائه."],"pts":["قوانين الإدراك: الشكل والأرضية، والتقارب، والتشابه، والإغلاق، والاستمرار.","الاستبصار مفاجئ ويبقى طويلاً وينتقل إلى مواقف مشابهة."],"traps":[],"src":"Köhler, The Mentality of Apes","aka":["الجشطلت","الاستبصار","كوهلر"]},"ar.l09.ausubel":{"k":"المعرفية","t":["Ausubel — Meaningful Reception Learning","أوزوبل: التعلم ذو المعنى"],"body":["أهم عامل في التعلم عند ديفيد أوزوبل **ما يعرفه المتعلم مسبقاً**: التعلم ذو المعنى يحدث حين تُربط المعلومة الجديدة بالبنية المعرفية، والحفظ المنفصل تعلم صم. ويمهد للدرس بـ**المنظم المتقدم**: مادة أعم وأشمل تُعرض قبله."],"pts":["المنظم المتقدم **شارح** (لغير المألوف) أو **مقارن** (يربط بالمألوف).","أنماط التعلم: (استقبال/اكتشاف) × (ذو معنى/صم)."],"ex":[],"traps":[],"src":"Ausubel, The Psychology of Meaningful Verbal Learning","aka":["أوزوبل","المنظم المتقدم","التعلم ذو المعنى"]},"ar.l09.bruner":{"k":"المعرفية","t":["Bruner — Discovery Learning","برونر: التعلم بالاكتشاف"],"body":["جيروم برونر رأى أن الطالب يتعلم أعمق حين **يكتشف** المبدأ بنفسه، والأنسب صفياً الاكتشاف الموجه."],"pts":["يمكن تعليم أي موضوع لأي طفل بصورة أمينة تناسب تفكيره.","شارك في صياغة مفهوم السقالات مع وود وروس."],"ex":["مكعبات تبني مستطيلات (عملي) ← رسمها على ورق مربعات (أيقوني) ← «المساحة = الطول × العرض» (رمزي)."],"traps":[],"src":"Bruner, The Process of Education","aka":["برونر","التعلم بالاكتشاف","المنهج الحلزوني"]},"ar.l09.adapt":{"k":"البنائية","t":["Piaget — Assimilation & Accommodation","بياجيه: التمثل والمواءمة والموازنة"],"body":["ينظم العقل خبراته في **مخططات (سكيما)**. و**التمثل** إدخال الخبرة الجديدة في مخطط قائم دون تغييره، و**المواءمة** تعديل المخطط أو بناء جديد حين لا تناسبه الخبرة. و**الموازنة** تستعيد التوازن بعد **اختلال التوازن** (الحيرة) فيرتقي التفكير."],"pts":["البنائية: المعلم **ميسّر**، والخطأ فرصة للتعلم، والتقويم بديل (مشاريع، حل مشكلات)."],"ex":["طفل يسمي الخفاش طائراً (تمثل)، ثم يعرف أنه يرضع صغاره فيحتار (اختلال)، فيعدل: «ليس كل ما يطير طائراً» (مواءمة)."],"traps":["الموازنة عملية منظمة لا مرحلة نمو."],"src":"Piaget, The Origins of Intelligence in Children","aka":["التمثل","المواءمة","الموازنة","المخطط","السكيما"]},"ar.l09.vygotsky":{"k":"البنائية","t":["Vygotsky — ZPD & Scaffolding","فيجوتسكي: منطقة النمو القريب"],"body":["**فيجوتسكي (البنائية الاجتماعية)**: **اجتماعي أولاً**، و**اللغة أداة التفكير**، و**الحديث الذاتي** تطور لا عيب؛ و**منطقة النمو القريب (المجاور)** بين **وحده** و**بمساعدة**، و**السقالات (الدعائم)** تُسحب."],"pts":["**السقالات**: دعم مؤقت متدرج (نموذج، تلميح، سؤال) يُسحب مع التقدم؛ صاغ المصطلح وود وبرونر وروس.","تطبيقاته: التعلم التعاوني، والأقران، والتدريس التبادلي."],"traps":[],"src":"Vygotsky, Mind in Society؛ Wood, Bruner & Ross (1976)","aka":["فيجوتسكي","منطقة النمو القريب","السقالات","الحديث الذاتي"],"ex":[]},"ar.l10.maslow":{"k":"الدافعية","t":["Maslow — Hierarchy of Needs","ماسلو: هرم الحاجات"],"body":["رتب أبراهام ماسلو الحاجات في هرم لا تبرز فيه الحاجة الأعلى حتى تُشبع الأدنى: **فسيولوجية ← أمن ← انتماء ← تقدير ← تحقيق الذات**. وفي الصورة السباعية تُضاف **المعرفية** ثم **الجمالية** قبل تحقيق الذات."],"pts":["الدنيا حاجات نقص، والعليا حاجات نمو."],"ex":[],"traps":["المعرفية والجمالية قبل تحقيق الذات لا بعده."],"src":"Maslow, Motivation and Personality","aka":["ماسلو","هرم الحاجات","تحقيق الذات"]},"ar.l10.selfeff":{"k":"الدافعية","t":["Bandura — Self-Efficacy","الكفاءة الذاتية"],"body":["اعتقاد الفرد بقدرته على إنجاز **مهمة محددة** بنجاح (ألبرت باندورا). تؤثر في اختيار المهام والجهد والمثابرة والقلق، وتختلف عن تقدير الذات العام."],"pts":["مصادرها: **خبرات الإتقان** (أقواها)، والخبرات البديلة، والإقناع اللفظي، والحالة الفسيولوجية والانفعالية.","تُبنى بمهام متدرجة تضمن نجاحاً مبكراً ونماذج من الأقران."],"ex":["طالب يخاف الإلقاء: جملتان أمام مجموعته، ثم دقيقة أمام نصف الفصل، ثم عرض كامل."],"traps":["الكفاءة الذاتية خاصة بالمهمة وليست تقدير الذات العام."],"src":"Bandura, Self-Efficacy: The Exercise of Control","aka":["الكفاءة الذاتية"]},"ar.l10.achieve":{"k":"الدافعية","t":["Achievement Motivation & Yerkes–Dodson","دافع الإنجاز وقانون يركس–دودسون"],"body":["قانون **يركس–دودسون**: العلاقة بين الاستثارة (القلق) والأداء منحنى مقلوب؛ الأداء الأفضل عند استثارة **متوسطة**، والمهام الصعبة تحتاج استثارة أقل."],"pts":["**العقلية النامية** (دويك): الذكاء ينمو بالجهد؛ ومدح الجهد والاستراتيجية يبنيها."],"traps":[],"src":"McClelland؛ Atkinson (1957)؛ Dweck, Mindset؛ Yerkes & Dodson (1908)","aka":["دافع الإنجاز","قانون يركس–دودسون","توجه الإتقان","العقلية النامية"]},"ar.l10.factor":{"k":"الذكاء","t":["Factor Theories of Intelligence","النظريات العاملية في الذكاء"],"body":["**جيلفورد**: بنية العقل (عمليات × محتوى × نواتج = 120 ثم 180 قدرة) وصاحب التمييز بين التقاربي والتباعدي."],"pts":["قدرات ثيرستون: فهم لفظي، طلاقة لفظية، عددية، مكانية، ذاكرة، سرعة إدراكية، استدلال."],"traps":[],"src":"Spearman (1904)؛ Thurstone, Primary Mental Abilities؛ Guilford, The Nature of Human Intelligence؛ Cattell (1963)","aka":["سبيرمان","ثيرستون","جيلفورد","بنية العقل","كاتل","الذكاء السائل","الذكاء المتبلور"]},"ar.l10.sternberg":{"k":"الذكاء","t":["Sternberg — Triarchic Theory","ستيرنبرغ: الذكاء الثلاثي"],"body":["رأى روبرت ستيرنبرغ أن الاختبارات التقليدية تقيس جانباً واحداً، واقترح ثلاثة أنواع متكاملة يسميها مجتمعة الذكاء الناجح."],"pts":["**التحليلي**: التحليل والمقارنة؛ ما تقيسه الاختبارات المدرسية.","**الإبداعي**: التعامل مع الجديد وتوليد الأفكار.","**العملي**: التكيف وحل مشكلات الحياة؛ «ذكاء الشارع»."],"ex":[],"traps":[],"src":"Sternberg, Beyond IQ","aka":["ستيرنبرغ","الذكاء الثلاثي","الذكاء العملي"]},"ar.l10.meta":{"k":"التفكير","t":["Flavell — Metacognition","ما وراء المعرفة"],"body":["**التفكير في التفكير** (جون فلافل): وعي الفرد بعملياته المعرفية والتحكم فيها بثلاث مهارات: **التخطيط** قبل المهمة، و**المراقبة** أثناءها، و**التقويم** بعدها."],"pts":["أسئلتها: ما خطتي؟ هل فهمت ما قرأت؟ كيف وصلت إلى الإجابة؟ هل هذه أفضل طريقة؟","استراتيجياتها: التفكير بصوت مسموع، وجدول KWL، والتقويم الذاتي، والمذكرات التأملية."],"traps":[],"src":"Flavell, Metacognition and Cognitive Monitoring (1979)","aka":["ما وراء المعرفة","التفكير في التفكير"]},"ar.l10.creative":{"k":"الإبداع","t":["Creative Thinking — Guilford & Torrance","التفكير الإبداعي ومكوناته"],"body":["**التفكير الإبداعي** نشاط عقلي هادف يُنتج حلولاً **جديدة وأصيلة**، أساسه **التفكير التباعدي**؛ ومراحل والاس: **الإعداد** ← **الاحتضان/الكمون** ← **الإلهام/الإشراق** ← **التحقق**."],"pts":["العصف الذهني (أوزبورن): الكم قبل الكيف، وإرجاء الحكم، والترحيب بالغريب، والبناء على أفكار الآخرين."],"traps":[],"src":"Guilford (1950)؛ Torrance Tests of Creative Thinking؛ Wallas, The Art of Thought؛ Osborn, Applied Imagination","aka":["التفكير الإبداعي","الطلاقة","المرونة","الأصالة","الإفاضة","العصف الذهني"]},"ar.l10.debono":{"k":"برامج التفكير","t":["de Bono — Six Hats & CoRT","ديبونو: القبعات الست وكورت"],"body":["إدوارد ديبونو دعا إلى تعليم التفكير مباشرة، وصاغ **التفكير الجانبي** (الخروج من الأنماط المعتادة). والقبعات الست تفصل أنماط التفكير فيلبس الجميع القبعة نفسها في الوقت نفسه."],"pts":[],"traps":["«أشعر أنها ستفشل» بلا تبرير = حمراء لا سوداء."],"src":"de Bono, Six Thinking Hats؛ CoRT Thinking Program","aka":["ديبونو","القبعات الست","برنامج كورت","التفكير الجانبي"]},"ar.l11.terms":{"k":"مداخل التدريس","t":["Approach, Strategy, Method, Style","المدخل والاستراتيجية والطريقة والأسلوب"],"body":[],"pts":["**المدخل**: إطار فكري (البنائي، القصصي، البيئي، التكاملي)."],"ex":["معلمة تتبنى المدخل البنائي، فتختار استراتيجية دورة التعلم، وتنفذ الاستكشاف بطريقة الاكتشاف الموجه، بأسلوبها الهادئ في طرح الأسئلة."],"traps":[],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار السابع؛ جويس وويل، نماذج التدريس","aka":["المدخل","الاستراتيجية","الطريقة","الأسلوب"]},"ar.l11.discovery":{"k":"المدخل المعرفي","t":["Discovery Learning — Bruner","التعلم بالاكتشاف (برونر)"],"body":[],"pts":["**الموجه**: المعلم يحدد المشكلة والأدوات والأسئلة؛ يناسب الصغار.","**شبه الموجه**: المعلم يحدد المشكلة مع بعض التوجيهات."],"ex":["معلمة تعطي الطالبات مغناطيساً وأشياء متنوعة وتسأل: ما الذي ينجذب؟ وما المشترك بينها؟ حتى يصلن إلى أنه يجذب بعض الفلزات كالحديد: اكتشاف موجه."],"traps":[],"src":"برونر، التعلم بالاكتشاف؛ المعايير التربوية العامة، مؤشر 7.1 (المدخل المعرفي)","aka":["الاكتشاف","التعلم بالاكتشاف","الاستقصاء"]},"ar.l11.problem":{"k":"طرق التدريس","t":["Problem Solving — Dewey","حل المشكلات (ديوي)"],"body":["جعل ديوي التفكير العلمي طريقة تدريس: موقف غامض فيه **هدف** و**مانع**، يتجاوزه الطالب بخطوات منظمة فيحدث **التعلم**."],"pts":["بعض الأسئلة تسمي الرابعة «اختبار الفروض» والأخيرة «الوصول إلى النتيجة».","المشكلات **محددة البنية** و**مفتوحة البنية**؛ والثانية أساس التعلم القائم على المشكلات."],"traps":[],"src":"ديوي، كيف نفكر؛ المعايير التربوية العامة، المعيار السابع","aka":["حل المشكلات"]},"ar.l11.project":{"k":"طرق التدريس","t":["Project Method — Kilpatrick","طريقة المشروعات (كلباترك)"],"body":["طوّر كلباترك، تلميذ ديوي، طريقة المشروعات: عمل هادف ممتد يختاره الطلاب ويخططونه وينفذونه، وينتهي **بمنتج ملموس** يُعرض ويُقوَّم. وذكر دليل المعلم في التعليم الإلكتروني 1447 «التعلم الإلكتروني القائم على المشاريع» ضمن الاستراتيجيات المقترحة."],"pts":["أنواعه عند كلباترك: إنشائية، واستمتاعية، ولحل مشكلة، ولكسب مهارة.","فردي أو جماعي، والمعلم مرشد ومتابع."],"traps":[],"src":"كلباترك، طريقة المشروع؛ دليل المعلم في التعليم الإلكتروني، الإصدار الثاني 1447","aka":["طريقة المشروعات","المشروعات"]},"ar.l11.coop":{"k":"الاستراتيجيات الاجتماعية","t":["Cooperative Learning — Johnson & Johnson","التعلم التعاوني"],"body":["التعلم التعاوني بنية تجعل نجاح الفرد مرتبطاً بنجاح المجموعة، وتجعل كل فرد مسؤولاً عن نصيبه. وإذا غاب أحد عناصره الخمسة عند جونسون وجونسون صار عملاً جماعياً تقليدياً."],"pts":["**الاعتماد الإيجابي المتبادل**: ننجح معاً أو نخفق معاً.","**المسؤولية الفردية**: يُقوَّم كل عضو على إسهامه.","**التفاعل وجهاً لوجه** و**المهارات الاجتماعية**.","**معالجة عمل المجموعة**: تقويم أدائها وتحسينه."],"traps":[],"src":"جونسون وجونسون، عناصر التعلم التعاوني","aka":["التعلم التعاوني"]},"ar.l11.jigsaw":{"k":"الاستراتيجيات الاجتماعية","t":["Jigsaw & STAD","جيكسو وفرق التحصيل"],"body":[],"pts":["في جيكسو لا يكتمل الدرس إلا بكل الأجزاء، فيقوى الاعتماد المتبادل.","في STAD يرفع الطالب الأضعف نقاط فريقه إذا تحسّن."],"traps":[],"src":"أرونسون (جيكسو)؛ سلافين (فرق التحصيل)","aka":["جيكسو","فرق التحصيل"],"ex":["معلمة تقسم درس «مناطق المملكة» أربعة أجزاء: تأخذ كل طالبة جزءاً، وتتعمق فيه مع صاحبات الجزء نفسه من المجموعات الأخرى، ثم تعود لتشرحه لمجموعتها الأم، ويُختم الدرس باختبار فردي."]},"ar.l11.conceptual":{"k":"التدريس البنائي","t":["Conceptual Change — Posner et al.","التغيير المفاهيمي"],"body":[],"pts":["أدوات الكشف: اختبار تشخيصي ثنائي الشق، ومقابلة، وخرائط مفاهيم، وتوقع – لاحظ – فسّر.","خطوات التدريس: **كشف التصورات القبلية** ← **تناقض معرفي** بحدث يخالف التوقع ← المفهوم العلمي ← تطبيقه ← مقارنة الطالب بين تصوره القديم والجديد."],"traps":[],"src":"بوسنر وزملاؤه، نموذج التغيير المفاهيمي؛ المعايير التربوية العامة، مؤشر 7.2","aka":["التغيير المفاهيمي","التغير المفاهيمي","التصورات البديلة","نموذج بوسنر"],"ex":[]},"ar.l12.behav":{"k":"الأهداف","t":["Behavioral Objective — Mager","الهدف السلوكي ومكوناته"],"body":[],"pts":["واضح لا يقبل إلا تفسيراً واحداً، و**بسيط** يتعلق بعملية واحدة.","يشتمل على الحد الأدنى للأداء المقبول، وواقعي قابل للتحقيق."],"ex":["«أن يتعرف الطالب على أهمية الماء» فعلها غير قابل للقياس؛ وبعد التعديل: «أن يذكر الطالب ثلاث فوائد للماء دون الرجوع إلى الكتاب»."],"traps":["«أن يعدد الطالب ويشرح أنواع الصخور» هدف مركب."],"src":"ماجر، صياغة الأهداف التعليمية؛ دليل الاختبارات: الأسس الفنية والعمليات الإجرائية 2025 (صياغة الأهداف بصورة سلوكية إجرائية)","aka":["الهدف السلوكي","الهدف الإجرائي"]},"ar.l12.smart":{"k":"الأهداف","t":["SMART Objectives","الأهداف الذكية SMART"],"body":["اختصار إنجليزي لخمس صفات يُفحص بها الهدف قبل اعتماده، يتقاطع مع شروط الهدف السلوكي ويضيف **الصلة** و**الإطار الزمني**."],"pts":["**S** محدد: سلوك واحد واضح.","**M** قابل للقياس: نعرف متى تحقق.","**A** قابل للتحقيق: يتحدى الطالب وهو في متناوله.","**R** وثيق الصلة بناتج التعلم والمعيار.","**T** محدد بزمن: نهاية الحصة أو الأسبوع."],"ex":["«أن يقرأ الطالب نصاً من 100 كلمة قراءة جهرية بأخطاء لا تزيد على 3 في نهاية الأسبوع الرابع»."],"traps":["هدف قابل للقياس لكنه مستحيل لمعظم الطلاب يخالف شرط **قابلية التحقيق**."],"src":"مراجع التخطيط للتدريس (معايير SMART)","aka":["SMART","الأهداف الذكية"]},"ar.l12.revised":{"k":"المجال المعرفي","t":["Revised Taxonomy — Anderson & Krathwohl (2001)","التصنيف المعدل وبعد المعرفة"],"body":["جعل أندرسون وكراثوول التصنيف **ثنائي البعد**: بعد العمليات المعرفية (ستة أفعال، الإبداع في قمتها)، وبعد المعرفة (أربعة أنواع). والتقاؤهما يكوّن جدولاً من 24 خلية يُوصف فيه الهدف بفعله ونوع معرفته معاً."],"pts":["**حقائقية**: مصطلحات وتفاصيل (رمز عنصر، تاريخ حدث).","**مفاهيمية**: تصنيفات ومبادئ ونظريات (مفهوم الكثافة).","**إجرائية**: خطوات وطرائق ومتى تُستخدم (خطوات حل معادلة).","**ما وراء معرفية**: وعي الطالب بتفكيره واستراتيجياته (كيف أذاكر؟)."],"ex":["«أن يطبق الطالب خطوات القسمة المطولة» = تطبيق × معرفة إجرائية."],"traps":["«ما وراء المعرفي» نوع معرفة، وليس مستوى سابعاً."],"src":"أندرسون وكراثوول (2001)، التصنيف المعدل","aka":["التصنيف المعدل","بعد المعرفة"]},"ar.l12.verbs":{"k":"المجال المعرفي","t":["Action Verbs by Level","أفعال مستويات بلوم"],"body":["الفعل أسرع مفتاح للتصنيف، بشرط النظر إلى **المهمة كاملة**؛ فـ«اشرح» قد تكون تذكراً إذا كان الشرح محفوظاً حرفياً."],"pts":["**تذكر**: يعدد، يسمي، يعرّف. **فهم**: يشرح، يفسر، يلخص، يعطي مثالاً.","**تطبيق**: يحل، يستخدم، يحسب في موقف جديد.","**تحليل**: يميز، يفكك، يبين السبب؛ و«يقارن» هنا إذا كانت المقارنة تفكيكاً للعلاقات.","**تقويم**: يحكم، ينقد، يبرر، يفاضل بمعيار.","**إبداع (تركيب)**: يصمم، يقترح، يؤلف، يخطط."],"ex":["«أيهما أفضل للترشيد: المصابيح الموفرة أم إطفاء الأجهزة؟ برّر» تقويم؛ «صمّم ملصقاً لحملة الترشيد» إبداع."],"traps":["«يميز» و«يفكك» **تحليل**؛ و«يقارن» محل خلاف: **فهم** في دليل الهيئة (مقارنة الحقائق ووصفها)، و**تحليل** في دليل الاختبارات 2025، فاحكم بالسياق."],"src":"دليل الاختبارات 2025 (الأفعال المرتبطة بمستويات بلوم)","aka":["أفعال بلوم"]},"ar.l12.krath":{"k":"المجال الوجداني","t":["Affective Domain — Krathwohl","المجال الوجداني (كراثوول)"],"body":["خمسة مستويات تقيس **درجة استدخال القيمة**: من الانتباه لها إلى أن تصير سمة ثابتة توجه السلوك."],"pts":["**الاستقبال**: الانتباه والإصغاء.","**الاستجابة**: المشاركة برضا والتطوع.","**التقييم**: تقدير القيمة وتبنيها والدفاع عنها.","**التنظيم**: ترتيب القيم في منظومة عند تعارضها.","**التميز بالقيمة (الوسم)**: القيمة جزء ثابت من الشخصية."],"ex":["طالب يسلّم محفظة وجدها (استجابة)، ثم يدافع عن الأمانة في نقاش (تقييم)، حتى يُعرف بين زملائه بالأمين (تميز بالقيمة).","«أن يشارك الطالب تطوعاً في حملة تنظيف الفصل» = استجابة."],"traps":[],"src":"كراثوول وبلوم وماسيا، تصنيف الأهداف: المجال الوجداني","aka":["كراثوول","المجال الوجداني"]},"ar.l12.simpson":{"k":"المجال النفس‑حركي","t":["Psychomotor Domain — Simpson","المجال النفس‑حركي (سمبسون)"],"body":["تصنيف سمبسون أشهر تصنيفات المهارات الحركية بسبعة مستويات، تبدأ بالإحساس والملاحظة وتنتهي بابتكار أداء جديد. ويقابله ديف (التقليد ← المعالجة ← الدقة ← الترابط ← التطبيع) وهارو."],"pts":["**الآلية**: أداء بثقة وعادة.","**الاستجابة المعقدة**: أداء ماهر سريع دقيق."],"ex":["طالب يقلد التصويب بتوجيه المعلم (استجابة موجهة)، ثم يصوب بثقة (آلية)، ثم يغير طريقته حين يتغير موقع المدافع (تكيف).","«أن يغسل يديه بالخطوات الصحيحة بإتقان دون تذكير» = آلية."],"traps":["**التطبيع** أعلى مستويات ديف لا سمبسون."],"src":"تصنيفات سمبسون وديف وهارو للمجال النفس‑حركي","aka":["سمبسون","المجال النفس‑حركي"]},"ar.l12.gagne":{"k":"خطة الدرس","t":["Gagné's Nine Events of Instruction","أحداث التدريس التسعة (جانييه)"],"body":["رتب روبرت جانييه الحصة الفعالة في تسعة أحداث متتابعة تقابل عمليات التعلم الداخلية، فيظهر موقع كل عنصر من عناصر الخطة."],"pts":["1) جذب الانتباه 2) إخبار المتعلمين بالأهداف 3) استثارة التعلم السابق.","4) عرض المحتوى 5) توجيه التعلم.","6) استدعاء الأداء 7) تقديم التغذية الراجعة.","8) تقويم الأداء 9) تعزيز الاحتفاظ والانتقال."],"traps":["الحدث الأول **جذب الانتباه** لا عرض المحتوى.","التغذية الراجعة **بعد الأداء** وقبل التقويم."],"src":"جانييه، شروط التعلم","aka":["جانييه","أحداث التدريس التسعة"]},"ar.l12.feedback":{"k":"التقويم من أجل التعلم","t":["Feedback","التغذية الراجعة"],"body":["معلومات يتلقاها الطالب عن أدائه تبين ما أحسن فيه، وما يحتاج إلى تحسين، وكيف. ومن مرتكزات لائحة تقويم الطالب 2025 تعزيز **التقويم من أجل التعلم** في الصف، والتغذية الراجعة قلبه."],"pts":["التعزيز تراكم **وجداني**، والتغذية الراجعة تراكم **معرفي**."],"ex":["بدل «أحسنت»: «رتبت خطوات الحل صحيحاً، وأخطأت في إشارة العدد في السطر الثالث؛ راجع ضرب السالب في السالب»."],"traps":[],"src":"لائحة تقويم الطالب في التعليم العام 2025، المادة 3 (مرتكزات تقويم الطالب)","aka":["التغذية الراجعة"]},"ar.l13.flipped":{"k":"نماذج التعلم","t":["Flipped Classroom","الصف المقلوب"],"body":["ينتقل الشرح إلى **المنزل** عبر مقطع قصير أو قراءة، وينتقل التطبيق إلى **الحصة** حيث المعلم حاضر ليساعد، فيُستثمر وقت الحصة في التفاعل والتفكير العالي. وأدرجه دليل المعلم في التعليم الإلكتروني 1447 ضمن الاستراتيجيات التي يفعّلها المعلم."],"pts":["قبل الحصة: مقطع قصير مع سؤال تحقق.","في الحصة: حل مسائل ونقاش ومشروع وتصحيح أخطاء.","من لم يشاهد المقطع يحتاج بديلاً سريعاً في بداية الحصة."],"ex":["معلم كيمياء يرفع على منصة مدرستي مقطعاً مدته ست دقائق عن موازنة المعادلات، ثم يوزع الطلاب في الحصة على مجموعات تحل معادلات متدرجة الصعوبة."],"traps":[],"src":"دليل المعلم في التعليم الإلكتروني، الإصدار الثاني 1447","aka":["الصف المقلوب","الفصل المقلوب"]},"ar.l13.pbl":{"k":"نماذج التعلم","t":["Problem-Based & Project-Based Learning","التعلم القائم على المشكلات والمشروعات"],"body":[],"pts":["المشكلات: البداية **مشكلة**، والنهاية حل مقترح مبرر.","المشروعات: البداية **سؤال محوري**، والنهاية **منتج**.","المعلم ميسّر يقوّم بسلالم تقدير معلنة."],"traps":[],"src":"دليل المعلم في التعليم الإلكتروني، الإصدار الثاني 1447","aka":["التعلم القائم على المشكلات","التعلم القائم على المشروعات"]},"ar.l13.5e":{"k":"النموذج البنائي","t":["5E Learning Cycle — Bybee","دورة التعلم الخماسية"],"body":["أصلها ثلاثي عند كاربلس (استكشاف، تقديم المفهوم، تطبيق)، وطوّرها بايبي إلى خمس مراحل يبدأ اسم كل منها بحرف E. وسمتها الأهم أن الطلاب **يجربون قبل أن يُشرح لهم**."],"pts":["**الانشغال**: إثارة الاهتمام وكشف المعرفة السابقة.","**التفسير**: الطلاب يفسرون والمعلم يقدم المصطلح.","**التقويم**: في كل مرحلة وفي النهاية."],"traps":[],"src":"بايبي، نموذج 5E؛ كاربلس، دورة التعلم","aka":["دورة التعلم","5E"]},"ar.l13.diff":{"k":"مؤشر 8.3","t":["Differentiated Instruction — Tomlinson","التعليم المتمايز"],"body":[],"pts":["**المحتوى**: ما يتعلمه الطالب أو مستوى المادة ومصادرها.","**العملية**: الأنشطة التي يفهم بها المفهوم نفسه.","**المنتج**: كيف يُظهر ما تعلمه.","**البيئة**: ترتيب المكان والمجموعات والجو الصفي.","يبدأ عادة بتقويم قبلي يوجه تقسيم المجموعات المرنة."],"ex":[],"traps":["التمايز **لا يعني** خفض الهدف للضعفاء ولا زيادة التمارين المتشابهة للمتفوقين."],"src":"توملينسون، الصف المتمايز؛ المعايير التربوية العامة، مؤشر 8.3","aka":["التعليم المتمايز","التدريس المتمايز"]},"ar.l13.elearn":{"k":"التقنية في التعليم","t":["E-learning & the Teacher's Role","أنماط التعليم الإلكتروني ودور المعلم"],"body":["تعرّف لائحة تقويم الطالب 2025 التعليم الإلكتروني بأنه توظيف تقنيات التعليم والمعلومات والاتصالات لرفع كفاية العملية التعليمية بجميع أنماطها وضبط جودتها. ويحدد دليل المعلم في التعليم الإلكتروني (الإصدار الثاني 1447) دور المعلم عبر منصة مدرستي وقنوات عين."],"pts":["قبل الدراسة: التحقق من الدخول إلى المنصة، والاطلاع على أدلتها وعلى **آداب السلوك الرقمي** والتحقق من اطلاع الطلاب عليها.","أثناء الدراسة: إعداد الدرس والخطة الأسبوعية، والحصة المتزامنة، و**رصد الحضور**، وإسناد الواجبات والاختبارات وتصحيحها مع **التغذية الراجعة**.","أدوات التقييم في الدليل: التقييم الإلكتروني، والتقييم الذاتي المفتوح عبر بنوك الأسئلة، والاختبارات المركزية.","الأصل الحضور في المدرسة، والالتحاق بالتعليم الإلكتروني استثناء في حالات خاصة (الإجراءات التنفيذية للائحة تقويم الطالب، القاعدة السادسة)."],"traps":[],"src":"دليل المعلم في التعليم الإلكتروني، الإصدار الثاني 1447؛ لائحة تقويم الطالب 2025 (التعريفات)؛ الإجراءات التنفيذية للائحة تقويم الطالب، القاعدة السادسة","aka":["التعليم الإلكتروني","التعليم المتزامن","التعليم غير المتزامن"]},"ar.l13.samr":{"k":"دمج التقنية","t":["SAMR & TPACK","النموذجان (SAMR, TPACK)"],"body":["نموذج **SAMR** (بونتيدورا) يقيس عمق أثر التقنية في المهمة: درجتان **تحسين** ودرجتان **تحويل**."],"pts":["**التعزيز**: بديل مع تحسين وظيفي (مدقق إملائي، تعليق فوري).","**التعديل**: إعادة تصميم كبيرة للمهمة."],"traps":[],"src":"بونتيدورا (SAMR)؛ ميشرا وكوهلر (TPACK)","aka":["SAMR","TPACK"],"ex":["كتابة الفقرة في مستند بدل الورق استبدال؛ وحين يعلّق الزملاء عليها فوراً تعزيز؛ وحين يتبادل الطلاب الرسائل مع طلاب مدرسة في مدينة أخرى صارت المهمة مستحيلة دون تقنية: إعادة تعريف."]},"ar.l14.expect":{"k":"مؤشر 9.1","t":["High Expectations — Pygmalion Effect","التوقعات العالية وأثر بجماليون"],"body":["في دراسة روزنثال وجاكوبسون (1968) أُخبر معلمون أن طلاباً اختيروا عشوائياً «سيزدهرون»، فتقدم هؤلاء فعلاً أكثر من غيرهم؛ لأن المعلم يعامل من يتوقع منه الكثير بطريقة مختلفة: ينتظره أكثر، ويكلفه بمهام أصعب، ويعطيه تغذية راجعة أدق. هذه **النبوءة التي تحقق ذاتها**."],"pts":["لإثارة الدافعية: ربط الدرس بحياة الطالب، و**أهداف قصيرة قابلة للتحقيق**، وتنويع الأنشطة، و**تغذية راجعة فورية وصفية**، ومهام فيها تحدٍّ مناسب.","مؤشرات الدافعية: يعمل بجد ولو بلا درجات، ويختار المهام الصعبة، و**يستثمر أخطاءه**، ويثابر؛ والمعلم يجمع **التحدي والدعم**."],"traps":[],"src":"روزنثال وجاكوبسون (1968)؛ المعايير التربوية العامة، مؤشر 9.1","aka":["أثر بجماليون","التوقعات العالية"]},"ar.l14.attrib":{"k":"الدافعية","t":["Attribution — Weiner; Self-Efficacy — Bandura","العزو والكفاءة الذاتية"],"body":[],"pts":["مصادر الكفاءة الذاتية من الأقوى: **خبرات الإتقان** ← رؤية نجاح الأقران ← الإقناع اللفظي ← الحالة الانفعالية.","الطالب الذي يتجنب مهمة بحجة ضعفه السابق فيها يعاني **إحباطاً**."],"ex":[],"traps":[],"src":"واينر، نظرية العزو؛ باندورا، الكفاءة الذاتية؛ سليجمان، العجز المتعلم","aka":["نظرية العزو","العزو","العجز المتعلم","الكفاءة الذاتية"]},"ar.l14.kounin":{"k":"إدارة الصف","t":["Kounin's Classroom Management","مفاهيم كونين في إدارة الصف"],"body":["حلل جاكوب كونين تسجيلات حصص كثيرة، فوجد أن الصفوف المنضبطة لا يميزها أسلوب العقاب، بل إدارة سير الدرس التي تمنع المشكلة قبل أن تبدأ وتبقي الطلاب منشغلين."],"pts":["**الزخم والسلاسة**: إيقاع مناسب وانتقالات بلا توقف أو قفز.","**تنبيه المجموعة**: إبقاء الجميع مستعدين (السؤال قبل تحديد المجيب)."],"traps":[],"src":"كونين، الانضباط وإدارة الجماعة في الصف","aka":["كونين","اليقظة","التداخل","أثر الموجة"],"ex":["معلم يشرح ويلاحظ طالبين يتهامسان في آخر الصف، فيتحرك نحوهما ويضع يده على طاولتهما دون أن يتوقف عن الشرح: توقف الهمس ولم ينقطع الدرس (يقظة وتداخل)."]},"ar.l14.canter":{"k":"إدارة الصف","t":["Assertive Discipline — Canter","الانضباط الحازم (كانتر)"],"body":["بنى لي ومارلين كانتر نموذجهما على مبدأ: للمعلم حق أن يعلّم، ولكل طالب حق أن يتعلم في صف آمن هادئ. ويميزان ثلاثة أساليب استجابة: **غير الحازم** (متردد لا يتابع)، و**العدائي** (يهدد ويهين)، و**الحازم** (واضح هادئ ثابت)."],"pts":["خطة الانضباط: **قواعد** قليلة واضحة، و**تقدير إيجابي** لمن يلتزم، و**عواقب** متدرجة معلنة مسبقاً.","تُطبق العاقبة بهدوء في كل مرة، بلا تفاوض لحظة المخالفة.","التقدير الإيجابي أساس الخطة، لا العقوبة."],"ex":["معلم يعلن في أول يوم عواقب متدرجة (تنبيه أول، فتنبيه ثانٍ، فتدوين وإشعار ولي الأمر)، ويرسل رسائل شكر أسبوعية لأولياء أمور الملتزمين، وحين يخالف طالب يقول بهدوء: «هذا التنبيه الأول» ويكمل."],"traps":["الحازم **ليس** العدائي؛ الصراخ والتهديد أسلوب عدائي."],"src":"كانتر، الانضباط الحازم","aka":["كانتر","الانضباط الحازم"]},"ar.l14.reinf":{"k":"تعديل السلوك","t":["Reinforcement & Punishment","التعزيز والعقاب"],"body":["يعرّف برنامج تعزيز السلوك الإيجابي 1445 التعزيز بأنه تقديم مثير إيجابي محبب، أو إزالة مثير سلبي مؤلم، بعد السلوك المرغوب **مباشرة**، مما يزيد احتمال تكراره. ويضرب مثلاً للتعزيز السلبي بطالب يحضّر دروسه ليتجنب توبيخ المعلم."],"pts":["الترتيب المقترح: الاجتماعية أولاً، فإن لم تُجدِ فالنشاطية، ثم المادية."],"traps":["الإكثار من المعزز نفسه يؤدي إلى **الإشباع** فيفقد أثره."],"src":"برنامج تعزيز السلوك الإيجابي 1445 (مفهوم التعزيز، أنواع المعززات، العوامل المؤثرة)؛ قواعد السلوك والمواظبة 1447، المادة 28","aka":["التعزيز","التعزيز الموجب","التعزيز السالب","العقاب"]},"ar.l14.schedules":{"k":"تعديل السلوك","t":["Schedules of Reinforcement","جداول التعزيز"],"body":["جداول التعزيز قواعد تنظم العلاقة بين السلوك والمعززات: متى أقدم التعزيز ومتى أؤجله؟ والاختيار يتبع مرحلة السلوك: **اكتسابه** أو **المحافظة عليه** (برنامج تعزيز السلوك الإيجابي 1445)."],"pts":["**المتقطع**: في بعض المرات؛ **الأكثر فاعلية ومقاومة للانطفاء**، ولا يُستخدم في مرحلة الاكتساب.","**الفترة**: تعزيز أول استجابة بعد مرور زمن ثابت أو متغير.","**النسبة**: تعزيز بعد عدد محدد من الاستجابات، ثابت أو متغير."],"ex":["طفل في الصف الأول يُعزَّز عند كل نطق صحيح للحرف (مستمر)، وبعد أن يتقنه يمدحه المعلم بين حين وآخر دون نمط ثابت (متقطع) فيبقى السلوك."],"traps":[],"src":"برنامج تعزيز السلوك الإيجابي 1445 (جداول التعزيز)","aka":["جداول التعزيز","التعزيز المتقطع","التعزيز المتواصل"]},"ar.l14.premack":{"k":"تعديل السلوك","t":["Premack, Token Economy, Shaping & Modeling","بريماك والاقتصاد الرمزي والتشكيل والنمذجة"],"body":[],"pts":["الاقتصاد الرمزي يناسب **الابتدائية**، والمعززات الاجتماعية أكثر فاعلية في المتوسطة والثانوية؛ ويُحدد مسبقاً موعد الاستبدال وعدد الرموز.","**النمذجة**: حية، ومصورة، وخيالية (القصص)."],"ex":["طالب لا يكتب إلا كلمة في التعبير؛ يعزز المعلم جملة، ثم جملتين، ثم فقرة قصيرة حتى يصل إلى الفقرة الكاملة: تشكيل."],"traps":[],"src":"برنامج تعزيز السلوك الإيجابي 1445 (أساليب تعزيز السلوك والخطوات الإجرائية)","aka":["مبدأ بريماك","الاقتصاد الرمزي","التشكيل","النمذجة"]},"ar.l14.rules1447":{"k":"تنظيم رسمي","t":["Student Behavior & Attendance Rules 1447","قواعد السلوك والمواظبة 1447: دور المعلم"],"body":["قواعد السلوك والمواظبة لطلبة التعليم العام (الإصدار الخامس 1447هـ) تخصص للسلوك 100 درجة من الثالث الابتدائي إلى الثالث الثانوي: **80** للسلوك الإيجابي يُعد كل طالب مستحقاً لها تلقائياً بداية كل فصل وتُحسم عند المخالفة مع فرص للتعويض، و**20** للسلوك المتميز. ومسمياتها الحالية: الموجه الطلابي ولجنة التوجيه الطلابي."],"pts":["في الابتدائية: تنبيه شفهي أول ← تنبيه ثانٍ مع حصر أسباب السلوك ← تدوين المشكلة وتوقيع الطالب وإشعار ولي الأمر هاتفياً وحسم درجة من الإدارة مع فرص التعويض، ثم التحويل إلى الموجه الطلابي.","ممنوع: الإيذاء الجسدي أو النفسي، والحرمان من الإفطار، و**نسخ الواجب عدة مرات عقاباً**، والسخرية من شخصية الطالب، و**إقصاؤه خارج الصف**."],"traps":[],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ: المادة 5، ودور المعلم، والمادة 6، والمادة 28","aka":["قواعد السلوك والمواظبة","لائحة السلوك والمواظبة"]},"ar.l14.questions":{"k":"مؤشر 9.4","t":["Questioning, Wait Time & Probing","الأسئلة الصفية وزمن الانتظار والسبر"],"body":["السؤال أكثر ما يفعله المعلم في الحصة. وجدت ماري بد رو أن المعلمين ينتظرون عادة أقل من ثانية بعد السؤال، وأن رفع الانتظار إلى 3–5 ثوانٍ يطيل الإجابات ويحسنها ويزيد مشاركة الأقل جرأة."],"pts":["زمن انتظار **بعد السؤال**، وآخر **بعد إجابة الطالب** قبل التعليق.","السبر: **توضيحي** (وضّح أكثر)، و**تبريري** (لماذا؟)، و**مشجع** (أسئلة تقود من الخطأ إلى الصواب)، و**محوّل** (إلى طالب آخر)."],"ex":[],"traps":[],"src":"رو، زمن الانتظار؛ المعايير التربوية العامة، مؤشر 9.4","aka":["زمن الانتظار","الأسئلة السابرة","السبر المشجع"]},"ar.l15.types":{"k":"أنواع التقويم","t":["Diagnostic, Formative & Summative","القبلي والتكويني والختامي"],"body":[],"pts":["**القبلي (ويسمى التشخيصي)**: في بداية العام أو الفترة أو المقرر أو الوحدة أو الدرس، للوقوف على استعداد الطالب ومعارفه ومهاراته السابقة.","في دليل الاختبارات 2025: دور المعلم في القبلي **تشخيص**، وفي التكويني **دعم وتيسير** والطالب فيه **تفاعلي**، وفي الختامي **تقييم**.","**التتبعي** بعد التقويم النهائي بفترة لمعرفة بقاء أثر التعلم، و**الانتقائي** لاختيار الطلاب لبرنامج أو مسار؛ وبحسب **الجهة المقوّمة**: **داخلي** (المدرسة)، **خارجي** (الوزارة أو الهيئة)، **متعدد الأطراف**."],"ex":[],"traps":[],"src":"لائحة تقويم الطالب في التعليم العام 2025، المادتان 1 و 3؛ دليل الاختبارات 2025 (أنواع التقويم التربوي)","aka":["التقويم القبلي","التقويم التكويني","التقويم الختامي","التقويم التشخيصي"]},"ar.l15.ref":{"k":"أنواع التقويم","t":["Criterion- vs Norm-Referenced","محكي المرجع ومعياري المرجع"],"body":[],"pts":["المحكي يجيب: هل أتقن؟ (رخصة القيادة، مستويات الأداء للصفين الأول والثاني).","المعياري يجيب: ما ترتيبه؟ (الانتقاء والمفاضلة، الرتب المئينية، الدرجات المعيارية).","دليل الاختبارات 2025: المعياري يميز بين مستويات الطلاب وفق منحنى التوزيع الاعتدالي.","نتائج المحكي قائمة بالأهداف المتحققة، ونتائج المعياري رتب مئينية ودرجات معيارية؛ والمعياري للانتقاء والتصفية والمفاضلة."],"traps":[],"src":"لائحة تقويم الطالب في التعليم العام 2025، المادة 1؛ دليل الاختبارات 2025 (أساليب تفسير النتائج)","aka":["محكي المرجع","معياري المرجع","ذاتي المرجع"]},"ar.l15.authentic":{"k":"التقويم البديل","t":["Authentic (Alternative) Assessment","التقويم البديل (الأصيل)"],"body":["يعرّفه دليل الاختبارات 2025 بأنه نهج يقيس التعلم بطرق غير تقليدية كالمشاريع والاختبارات العملية، ويقيس استخدام الطالب للمعرفة في حياته ومهارات كالعمل الجماعي وتنظيم الوقت، ويتطلب **الدمج** بينه وبين التقويم التقليدي للوصول إلى حكم دقيق."],"pts":["من شروطه: **العدالة** (فرص متساوية ومحكات معلنة مسبقاً) والتعدد في الأدوات."],"traps":[],"src":"دليل الاختبارات: الأسس الفنية والعمليات الإجرائية 2025 (التقويم البديل)","aka":["التقويم البديل","التقويم الأصيل","قائمة الشطب","سلم التقدير"]},"ar.l15.rubric":{"k":"أدوات التقويم","t":["Rubrics","سلم التقدير الوصفي (الروبرك)"],"body":["جدول يضع **معايير** الأداء في جانب و**مستويات** الجودة في جانب، ويصف كل خلية بعبارة تقول كيف يبدو الأداء في هذا المستوى، مع درجة لكل مستوى. يُعلن قبل المهمة، فيعرف الطلاب المطلوب ويقوّمون أنفسهم به."],"pts":["**التحليلي**: درجة لكل معيار ← تغذية راجعة تفصيلية.","**الكلي**: درجة واحدة لوصف عام ← أسرع وأقل تفصيلاً."],"ex":["معيار «تنظيم الفقرة»: 4 = جملة مفتاحية وثلاث جمل داعمة مترابطة وخاتمة؛ 3 = جمل داعمة مع ضعف في الربط؛ 2 = جمل غير مرتبة؛ 1 = جمل متفرقة بلا فكرة رئيسة."],"traps":[],"src":"دليل الاختبارات 2025 (أساليب التقويم وأدواته)","aka":["الروبرك","سلم التقدير الوصفي"]},"ar.l15.portfolio":{"k":"أدوات التقويم","t":["Portfolio","ملف الإنجاز"],"body":["جمع منظم وهادف لشواهد تعلم الطالب يبين جهوده وتقدمه، لكل قطعة فيه سبب، ويكتب الطالب تأمله عليها؛ فهدفه الأساسي **التأمل الذاتي** ومتابعة التقدم. وفي الإجراءات التنفيذية للائحة تقويم الطالب يُوثَّق مستوى طالب الصفين الأول والثاني بشواهد في «ملف إنجاز الطالب»."],"pts":["أنواعه: ملف عمل (المسودات)، وملف عرض (أفضل الأعمال)، وملف تقويم (شواهد على معايير).","مكوناته: أعمال مؤرخة، وتأملات الطالب، وتقويم المعلم.","يُقوَّم بروبرك معلن ويُراجع دورياً مع الطالب."],"traps":[],"src":"الإجراءات التنفيذية للائحة تقويم الطالب، القاعدة الثانية","aka":["ملف الإنجاز","البورتفوليو"]},"ar.l15.objective":{"k":"أنواع الأسئلة","t":["Objective Items & Writing Rules","الأسئلة الموضوعية وقواعد صياغتها"],"body":[],"pts":["**الاختيار من متعدد**: مقدمة تحمل المشكلة كاملة، وبدائل متجانسة معقولة متقاربة الطول، وموقع الإجابة متغير، وتجنب «جميع ما سبق» و«لا شيء مما سبق».","**الصواب والخطأ**: فكرة واحدة، بلا كلمات جزم (دائماً، أبداً، جميع) ولا نفي مزدوج.","**الإكمال**: فراغ واحد مهم قرب آخر الجملة، دون نقل حرفي من الكتاب."],"ex":[],"traps":[],"src":"دليل الاختبارات 2025 (الاختبارات التحريرية)","aka":["الأسئلة الموضوعية","الاختيار من متعدد"]},"ar.l15.tos":{"k":"بناء الاختبار","t":["Table of Specifications","جدول المواصفات"],"body":["يعرّفه دليل الاختبارات 2025 بأنه مخطط تفصيلي **ثنائي البعد** يربط موضوعات المحتوى بالأهداف، ويبين الوزن النسبي لكل موضوع ولكل مستوى. يُبنى بعد تحديد الأهداف وتحليل المحتوى وقبل كتابة الأسئلة، ووظيفته الأولى **صدق المحتوى**."],"pts":["أسئلة الخلية = العدد الكلي × وزن الموضوع × وزن المستوى.","لا تقل فقرات كل ناتج تعلم عن 3–4 فقرات، وتُرتب بحسب النوع ثم من الأسهل إلى الأصعب.","**مثال**: 50 سؤالاً لثلاث وحدات حصصها 4 و 8 و 8 (من 20) ← 10 و 20 و 20 سؤالاً؛ وبأوزان مستويات 20% و 40% و 40% تصبح الوحدة الأولى 2 و 4 و 4، والثانية والثالثة 4 و 8 و 8 لكل منهما (المجموع 50)."],"traps":[],"src":"دليل الاختبارات: الأسس الفنية والعمليات الإجرائية 2025 (إعداد جداول المواصفات؛ عدد الفقرات وترتيبها)","aka":["جدول المواصفات"],"ex":[]},"ar.l15.reg":{"k":"تنظيم رسمي","t":["Student Assessment Regulation 2025","لائحة تقويم الطالب 2025: الدرجات والنجاح"],"body":["تحكم لائحة تقويم الطالب في التعليم العام (2025) وإجراءاتها التنفيذية ودليل توزيع درجات المواد الدراسية 2025 أرقام التقويم: لكل مادة **100 درجة** في كل فترة."],"pts":["النجاح: **النهاية الصغرى 50%**، و**النسبة الشرطية 20%** من درجة الاختبار التحريري (نهاية العام في الابتدائية والمتوسطة، ونهاية كل فترة في الثانوية)، ويُشترط في الابتدائية والمتوسطة أداء الاختبار الختامي.","اختبارات تحريرية قصيرة من **20 درجة مرتين على الأقل** في الفترة (دليل التوزيع 2025).","**لا تُطبق النسبة الشرطية على الدور الثاني**؛ وفيه يحتفظ الطالب بـ 40 درجة ويُختبر من 60.","يستمر تحسين درجات الأدوات التكوينية حتى بدء اختبارات نهاية الفترة؛ وللسلوك 100 درجة وللمواظبة 100."],"ex":[],"traps":[],"src":"لائحة تقويم الطالب في التعليم العام 2025 (المواد 1 و 5 و 6)؛ الإجراءات التنفيذية للائحة تقويم الطالب، القاعدتان 3 و 4؛ دليل توزيع درجات المواد الدراسية 2025","aka":["لائحة تقويم الطالب","النسبة الشرطية","النهاية الصغرى"]},"ar.l15.levels":{"k":"تنظيم رسمي","t":["Performance Levels — Grades 1–2","مستويات الأداء للصفين الأول والثاني"],"body":["مستويات الأداء خاصة **بالصفين الأول والثاني الابتدائي** (والصف الأول للتعليم المستمر): يُقوَّم الطالب تكوينياً بمستوى إتقانه لكل معيار من معايير المادة، عدا **الرياضيات واللغة العربية** فتُقوَّمان قبلياً وتكوينياً وختامياً بالدرجات. ومن الصف الثالث فما فوق التقويم بالدرجات."],"pts":["**متفوق** 95% فأكثر من المعايير، و**متقدم** من 85% إلى أقل من 95%، و**متمكن** من 75% إلى أقل من 85% (وكلها بما فيها معايير الحد الأدنى).","يدوّن المعلم تقويمه **يومياً** في سجل متابعة تقويم الطالب، ويرصد الخلاصة في النظام الرقمي نهاية الفترة موثقة بشواهد في ملف إنجاز الطالب.","من لم يتقن معياراً من **معايير الحد الأدنى** يُحال إلى لجنة التوجيه الطلابي، ويستمر تقويمه فيه حتى نهاية العام."],"traps":["مستويات الأداء **للصفين الأول والثاني فقط**، وتُستثنى منها الرياضيات واللغة العربية."],"src":"لائحة تقويم الطالب في التعليم العام 2025، المادة 5؛ الإجراءات التنفيذية للائحة تقويم الطالب، القاعدة الثانية","aka":["مستويات الأداء"]},"ar.l16.validity":{"k":"خصائص الاختبار","t":["Validity","الصدق وأنواعه"],"body":["الصدق أن يقيس الاختبار ما وُضع لقياسه فعلاً؛ ويصفه دليل الاختبارات 2025 بأن «يتوافق التقويم مع الأهداف، ويقيس ما هو مخصص لقياسه»."],"pts":["**الصدق العيني**: كفاية **عدد الأسئلة** لتمثيل المادة، ويقابله **الصدق المنطقي**: تمثيل الموضوعات."],"traps":[],"src":"دليل الاختبارات 2025 (خصائص التقويم الصفي الفعال)؛ مراجع القياس والتقويم التربوي","aka":["الصدق","صدق المحتوى","صدق المحك","صدق البناء","الصدق الذاتي"]},"ar.l16.reliab":{"k":"خصائص الاختبار","t":["Reliability & Objectivity","الثبات والموضوعية"],"body":["الثبات اتساق النتائج واستقرارها عند تكرار القياس، ويصفه دليل الاختبارات 2025 بأن نتائج التقويم «ثابتة نسبياً عند تكرار العملية في نفس الظروف»."],"pts":["**إعادة التطبيق** (معامل الاستقرار): الاختبار نفسه مرتين؛ عيبه أثر التذكر إذا قصرت المدة.","**ثبات المصححين**: ارتباط درجات مصححين مستقلين؛ مؤشر على الموضوعية في المقالي."],"traps":[],"src":"دليل الاختبارات 2025 (خصائص التقويم الصفي الفعال)؛ مراجع القياس والتقويم التربوي","aka":["الثبات","الموضوعية","إعادة التطبيق"]},"ar.l16.coef":{"k":"معاملات الثبات","t":["Reliability Coefficients & SEM","معاملات الثبات والخطأ المعياري"],"body":["معاملات الاتساق الداخلي تُحسب من تطبيق واحد، ولكل منها موضع. والخطأ المعياري للقياس يترجم الثبات إلى وحدات الدرجة: كم تتذبذب درجة الطالب حول درجته الحقيقية."],"pts":["**سبيرمان براون**: ر الكلي = 2ر ÷ (1 + ر). مثال: ارتباط النصفين 0.60 ← 1.20 ÷ 1.60 = **0.75**.","**كودر ريتشاردسون (KR-20)** للفقرات الثنائية: [ك ÷ (ك − 1)] × [1 − (مجموع ص×خ ÷ التباين الكلي)]. مثال: ك = 10، ومجموع ص×خ = 1.8، والتباين 6 ← (10 ÷ 9) × 0.7 ≈ **0.78**.","**كرونباخ ألفا**: الصيغة نفسها بمجموع تباينات الفقرات؛ للمقاييس المتدرجة والمقالية."],"traps":[],"src":"مراجع القياس والتقويم التربوي (معادلات الثبات)","aka":["سبيرمان براون","كودر ريتشاردسون","كرونباخ ألفا","الخطأ المعياري للقياس"]},"ar.l16.difficulty":{"k":"تحليل الفقرات","t":["Item Difficulty Index","معامل الصعوبة"],"body":[],"pts":["**بالمجموعتين**: (صحيح العليا + صحيح الدنيا) ÷ أفراد المجموعتين. مثال: (7 + 3) ÷ 16 ≈ **0.63**.","المدى المقبول الشائع في المراجع 0.20–0.80، و 0.50 مثالي."],"traps":["فقرة 0.85 خارج المدى الشائع وخارج توصية الدليل: سهلة جداً تُراجع."],"src":"دليل الاختبارات: الأسس الفنية والعمليات الإجرائية 2025 (تحليل فقرات الاختبار: معامل الصعوبة)","aka":["معامل الصعوبة","معامل السهولة"],"ex":[]},"ar.l16.discrim":{"k":"تحليل الفقرات","t":["Item Discrimination Index","معامل التمييز"],"body":["يقيس قدرة الفقرة على التفريق بين المتمكنين والأقل تمكناً: نرتب الأوراق تنازلياً، ونأخذ أعلى 27% وأدنى 27%، ونقارن أداء الفئتين. ويحسبه دليل الاختبارات 2025 بالدرجات فيصلح للمقالي، **ويقبله ضمن المدى 0.40 – 1.00**."],"pts":["**الموضوعي**: (صحيح العليا − صحيح الدنيا) ÷ عدد إحدى الفئتين. مثال: 30 طالباً ← 8 في كل فئة؛ 7 و 3 ← 4 ÷ 8 = **0.50**.","**صيغة الدليل**: (مجموع درجات العليا − مجموع الدنيا) ÷ (عدد إحدى الفئتين × درجة السؤال). مثال مقالي من 4: (26 − 14) ÷ 32 ≈ **0.38**.","**سالب**: 2 من العليا و 5 من الدنيا ← −3 ÷ 8 ≈ **−0.38**؛ تُحذف الفقرة أو تُراجع.","التفسير الشائع: 0.40 فأعلى ممتاز، و 0.30–0.39 جيد، و 0.20–0.29 يحتاج تعديلاً، وأقل من 0.20 ضعيف؛ ودليل الاختبارات 2025 يقبل التمييز ضمن المدى 0.40–1.00، فما بين 0.20 و 0.39 يُراجع ويُعدَّل ولا يُحذف."],"traps":["التمييز السالب يعني أن **الأقل تمكناً أجابوا أفضل**؛ غالباً خطأ في المفتاح أو غموض.","فقرة يجيبها الجميع تمييزها **صفر**."],"src":"دليل الاختبارات: الأسس الفنية والعمليات الإجرائية 2025 (معامل تمييز الفقرة)","aka":["معامل التمييز","التمييز السالب"],"ex":["فقرة أجاب عنها 7 من الفئة العليا (8 طلاب) و 3 من الدنيا (8 طلاب): الصعوبة (7 + 3) ÷ 16 ≈ 0.63، والتمييز (7 − 3) ÷ 8 = 0.50؛ فقرة متوسطة ممتازة التمييز."]},"ar.l16.distract":{"k":"تحليل الفقرات","t":["Distractor Analysis","تحليل فعالية المشتتات"],"body":[],"pts":["مثال: المفتاح (ب)، و 8 طلاب في كل فئة.","(أ): عليا 0، دنيا 4 ← **فعال**.","(ب) المفتاح: عليا 6، دنيا 2 ← صعوبة 8 ÷ 16 = 0.50، وتمييز 4 ÷ 8 = 0.50.","(ج): عليا 2، دنيا 2 ← **غير مميز** يُراجع؛ (د): لم يختره أحد ← **غير فعال** يُستبدل.","المشتت الذي تختاره العليا أكثر يُراجع؛ قد يكون غامضاً أو إجابة صحيحة ثانية."],"traps":[],"src":"مراجع القياس والتقويم التربوي (تحليل الفقرات)","aka":["المشتت الفعال","فعالية المشتتات"]},"ar.l16.central":{"k":"الإحصاء الوصفي","t":["Measures of Central Tendency","النزعة المركزية"],"body":[],"pts":["**الوسيط**: القيمة الوسطى بعد الترتيب، وفي العدد الزوجي متوسط القيمتين الوسطيين؛ الأنسب للبيانات الملتوية.","**المنوال**: الأكثر تكراراً؛ للبيانات النوعية، وقد يتعدد."],"traps":[],"src":"دليل الاختبارات 2025 (مقاييس النزعة المركزية)","aka":["المتوسط الحسابي","الوسيط","المنوال"]},"ar.l16.spread":{"k":"الإحصاء الوصفي","t":["Measures of Dispersion","مقاييس التشتت"],"body":[],"pts":["**المدى** = أكبر قيمة − أصغر قيمة؛ أبسطها وأكثرها تأثراً بالمتطرفات.","مثال: 2، 4، 4، 4، 5، 5، 7، 9 ← المتوسط 5، ومربعات الانحرافات 9، 1، 1، 1، 0، 0، 4، 16 (مجموعها 32) ← التباين 32 ÷ 8 = **4** ← الانحراف **2**."],"traps":["تباين 81 ← انحراف **9**."],"src":"دليل الاختبارات 2025 (مقاييس التشتت)","aka":["المدى","التباين","الانحراف المعياري"]},"ar.l16.normal":{"k":"التوزيع","t":["Normal Distribution & Skewness","المنحنى الاعتدالي والالتواء"],"body":["تطلب لائحة تقويم الطالب 2025 في التقويم التكويني «توزيعاً منطقياً للدرجات»: منحنى يرتفع عند الوسط وينخفض تدريجياً عند الطرفين، لمعالجة تضخم الدرجات."],"pts":["مثال: متوسط 60 وانحراف 8 ← نحو 68% بين 52 و 68، ونحو 95% بين 44 و 76.","نحو **34%** بين المتوسط وانحراف واحد فوقه، ونحو **2.3%** (2.28% بالدقة) فوق انحرافين؛ وفي الالتواء السالب معظم الدرجات مرتفعة (اختبار سهل أو تدريس فعّال)."],"traps":[],"src":"لائحة تقويم الطالب في التعليم العام 2025، المادة 1 (توزيع منطقي للدرجات)؛ مراجع الإحصاء التربوي","aka":["التوزيع الاعتدالي","الالتواء الموجب","الالتواء السالب"]},"ar.l16.z":{"k":"الدرجات المعيارية","t":["Standard Scores (z, T) & Percentile Rank","الدرجات المعيارية والرتبة المئينية"],"body":[],"pts":["مثال: 80 (متوسط 70، انحراف 5) ← ز = 2 ← ت = 70؛ و 54 (متوسط 60، انحراف 4) ← ز = −1.5 ← ت = 35.","**الرتبة المئينية** ≈ (عدد من درجاتهم أقل ÷ العدد الكلي) × 100؛ مثال: 30 من 40 دونه ← **75**."],"traps":[],"src":"مراجع القياس والتقويم التربوي (الدرجات المعيارية والمئينية)","aka":["الدرجة المعيارية","الدرجة التائية","الرتبة المئينية"],"ex":[]},"ar.l01.wasat":{"k":"قيمة","t":["Moderation (Wasatiyyah)","الوسطية والاعتدال"],"aka":["الوسطية","الاعتدال","الغلو","التطرف الفكري"],"body":["المعايير المهنية تطلب أن يكون المعلم نموذجاً في الامتثال **بالقيم الإسلامية الوسطية السمحة**، وأن يصمم أنشطة تعزز قيم الوسطية والتسامح والاعتدال ونبذ التطرف. وفي مدونة 1447 تأتي القيم نفسها واجبات: **التحلي بالنزاهة والصدق والأمانة والتسامح والرفق والعدالة**، ويُحظر **اعتناق الأفكار المتطرفة أو نشرها**."],"pts":["قواعد السلوك 1447 تجعل من دور المعلم: **تعزيز التنوع الثقافي والوسطية والاعتدال الفكري، والتأكد من سلامة البيئة التعليمية من الفكر المتطرف**.","من حالات الإبعاد عن التدريس في لائحة الوظائف: **تبني اتجاهات فكرية منحرفة** أثناء أداء الواجب التعليمي بما يؤثر سلباً في الطلاب (المادة 14).","ندوة أو برنامج عن **التطرف الفكري** يُصنَّف قضية مجتمعية يزوّد المعلم طلابه بخبرات عنها."],"ex":["طالب في الثاني المتوسط يصف زميله بالتقصير لأنه لا يلتزم بنافلة معينة. المعلم لا يوبخ ولا يجاري، بل يوضح بهدوء الفرق بين الواجب والمستحب ويذكّر بأدب النصيحة. لا غلو في الحكم على الآخرين، ولا تهوين من القيم."],"traps":["الوسطية ليست «منطقة رمادية» بلا مواقف؛ الثوابت تُعلَّم بوضوح، والاعتدال في الأسلوب والحكم.","خيار «أتجنب الحديث عن القيم حتى لا أُتهم بالتشدد» تفريط لا وسطية."],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (1.1)؛ مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادتان 6 و 14)؛ قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ (دور المعلم)؛ لائحة الوظائف التعليمية بتعديلات 1446هـ (المادة 14)"},"ar.l01.neutral":{"k":"موقف صفي","t":["Professional Neutrality","الحياد في القضايا الخلافية"],"aka":["الحياد المهني","الخلافية","القضايا الخلافية"],"body":["وواجب المعلم ألا يحوّل الحصة إلى منبر لرأيه الشخصي، وأن يحيل الطالب إلى المصادر الموثوقة والجهات المختصة.","مدونة 1447 نصت على ذلك في واجبات المعلم مع طلابه: **تجنب الدخول في نقاشات حول القضايا ذات الحساسية، مثل التيارات الدينية والقضايا الفقهية الخلافية والشؤون السياسية** (المادة 8)، وفي الواجبات العامة: **توخي الموضوعية والعمل بحيادية دون تمييز** (المادة 6)."],"pts":["الحياد **لا يعني إسكات الطالب**: يستمع إليه باحترام، ويبيّن أن المسألة محل خلاف، ويوجهه إلى المرجع المختص.","تحظر المدونة **معارضة القرارات الصادرة من الجهات العليا والتشكيك في مصداقيتها وإثارة الرأي العام** (المادة 14)."],"ex":["طالب في الثانوية يسأل معلم الرياضيات عن حكم مسألة فقهية مختلف فيها ويطلب رأيه. يجيب المعلم: «هذه مسألة فيها أقوال لأهل العلم، وأحسن من يجيبك عنها معلم العلوم الشرعية أو أهل الفتوى المعتمدون»، ثم يعود إلى هدف الدرس."],"traps":["خيار «يرفض السؤال ويوبخ الطالب» خاطئ أيضاً؛ الصحيح الإحالة الهادئة."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المواد 6 و 8 و 14)"},"ar.l01.dialogue":{"k":"موقف صفي","t":["Culture of Dialogue","ثقافة الحوار مع الطالب المختلف"],"aka":["ثقافة الحوار","الأدلة المنطقية والقدوة العملية"],"body":["المؤشر 1.1 للممارس يطلب أن **يناقش الأفكار المختلفة، ويتقبل اختلاف وجهات نظر الآخرين، ويوظف المواقف الصفية في تنمية ثقافة الحوار**. فالطالب الذي يجادل أو يشكك فرصة تعليمية لا تهديد."],"pts":["خطوات الحوار: **إنصات ← توضيح ← أدلة وشواهد ← اتفاق على المشترك**.","مدونة 1447: **احترام التنوع في وجهات النظر** (المادة 10)."],"ex":["طالب يقول في درس التاريخ: «ما فائدة دراسة الماضي؟». يعيد المعلم السؤال للصف، ويجمع إجابات الطلاب، ثم يعرض مثالاً من تأسيس الدولة السعودية يبيّن كيف تشرح الأحداث حاضرنا، فيتحول الاعتراض إلى نقاش يحقق الهدف."],"traps":["الحوار لا يعني التسوية بين الثوابت والآراء؛ الثوابت تُبيَّن بأدلتها."],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (1.1، مؤشر الممارس 3)؛ مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادة 10)"},"ar.l01.krathwohl":{"k":"نظرية","t":["Krathwohl's Affective Taxonomy","تصنيف كراثول للمجال الوجداني"],"aka":["كراثول","تمثّل القيمة"],"body":["صنّف ديفيد كراثول (David Krathwohl) مع زملائه أهداف المجال الوجداني (المشاعر والقيم والاتجاهات) في خمسة مستويات متدرجة، كل مستوى يبني على ما قبله، من مجرد الانتباه للقيمة حتى تصبح جزءاً من شخصية المتعلم.","ويفيد المعلم في صياغة أهداف القيم: بدل «أن يحب الطالب وطنه» (لا يُقاس) يكتب سلوكاً يدل على المستوى: يصغي، يشارك، يدافع، يوازن، يتمثّل."],"pts":["3. **التقييم (التقدير)**: يقدّر القيمة ويتبناها ويدافع عنها.","4. **التنظيم**: يرتب القيم في منظومة ويوازن بينها عند التعارض."],"ex":["في قيمة المحافظة على المرافق: يصغي الطالب للشرح (استقبال)، ثم يشارك في حملة الصف (استجابة)، ثم يدافع عن القيمة أمام زملائه (تقدير)، ثم يوازن بين رغبته في اللعب ونظافة الملعب (تنظيم)، ثم يحافظ على المرافق تلقائياً حتى خارج المدرسة (تمثّل)."],"traps":["لا تخلط كراثول (وجداني) بتصنيف بلوم (معرفي) أو تصنيفات المجال المهاري."],"src":"تصنيف الأهداف التربوية في المجال الوجداني (كراثول وزملاؤه)"},"ar.l01.diversity":{"k":"قيمة","t":["Cultural Diversity & Coexistence","التنوع الثقافي والتعايش"],"aka":["التنوع الثقافي","التعايش","التسامح","التفاعل الإيجابي مع الثقافات الأخرى"],"body":["مدونة 1447 تجمع الأمرين في فقرة واحدة: ينمي لدى الطلاب الاعتزاز بدينهم والولاء لمليكهم والانتماء لوطنهم، **كما يعزز لديهم أهمية التفاعل الإيجابي مع الثقافات الأخرى** (المادة 8). وتطلب **احترام التنوع في وجهات النظر** (المادة 10)، و**العدالة والإنصاف في معاملة جميع الطلاب دون تمييز** (المادة 8)."],"pts":["التعامل مع زميل عمل غير مسلم يكون **وفق مقتضيات مهام العمل** وباحترام؛ والمدونة تطلب التعامل مع الزملاء **دون تمييز** (المادة 13)."],"ex":["في فصل ابتدائي فيه طلاب من خمس جنسيات، تطلب المعلمة من كل طالب أن يحكي كيف يُكرم الضيف في بيته، ثم تجمع القواسم المشتركة على السبورة: الترحيب، والطعام، والبشاشة. نشاط واحد عزز الاحترام وربطه بقيمة الكرم في ثقافتنا."],"traps":[],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المواد 8 و 10 و 13)؛ المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (1.2)؛ قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ (دور المعلم)"},"ar.l01.techcode":{"k":"مدونة 1447","t":["Technology Duties in the 1447 Code","واجبات المعلم التقنية في مدونة 1447"],"aka":["حقوق النشر","نظام مكافحة الجرائم المعلوماتية"],"body":["الباب الرابع من مدونة 1447 خاص بالتقنية: الأجهزة، والإنترنت، والبريد الإلكتروني، ومواقع التواصل الاجتماعي. والفكرة الجامعة أن المعلم يمثل التعليم في كل ما ينشره ويستخدمه.","وتطلب المدونة من المعلم في مواقع التواصل أن يستخدمها بما يعكس السلوك المهني، **مع الاطلاع والتقيد بنظام مكافحة الجرائم المعلوماتية** (المادة 21)."],"pts":["**نظام مكافحة الجرائم المعلوماتية** (1428هـ) يجرّم التنصت والابتزاز والتهديد والتشهير وتغيير معلومات المواقع والدخول غير المشروع.","**الإنترنت** (المادة 19): الالتزام **بحقوق الملكية الفكرية** وشروط الترخيص، و**التأكد من سلامة المحتوى المعروض أمام الطلاب**، وإبلاغ الإدارة فوراً عن أي أمر غير معتاد.","**الذكاء الاصطناعي** (المادة 19): الالتزام بسياسات الاستخدام المعتمدة، واحترام خصوصية البيانات، وتجنب الاعتماد الكلي عليه في القرارات الحساسة.","**البريد** (المادة 20): الحكومي للمراسلات الرسمية فقط، ولا يُستخدم البريد الشخصي في المراسلات الرسمية.","**التواصل الاجتماعي** (المادة 21): يتجنب **التصوير أو نشر أي محتوى يتعلق بالمدرسة أو الطلاب أو الزملاء**، ولا يسرّب القرارات والتعاميم، ولا يدير حساباً باسم جهته ما لم يُعيَّن متحدثاً رسمياً.","**الأجهزة** (المادة 18): لا يحمّل برامج أو يستخدم وحدات تخزين خارجية إلا بعد مراجعة الإدارة المختصة، ويحافظ على **كلمة السر**."],"ex":[],"traps":["«الحساب شخصي فلا شأن للوزارة» خطأ؛ المدونة تنظم سلوك المعلم في حساباته الشخصية.","الذكاء الاصطناعي **مسموح بضوابط**، لا ممنوع مطلقاً ولا مطلق بلا قيود."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ، الباب الرابع (المواد 18–21)"},"ar.l01.privacy":{"k":"مدونة 1447","t":["Student Privacy & Data","خصوصية الطالب ونشر الصور والمعلومات"],"aka":["خصوصية الطالب","مراجعة لوائح الوزارة"],"body":["معلومات الطالب ووثائقه وصوره أمانة. مدونة 1447 تطلب **التعامل مع الوثائق والمعلومات الشخصية للطلاب بسرية تامة وفقاً للأنظمة والتعليمات** (المادة 8)، و**الالتزام بنظام حماية البيانات الشخصية** ولائحته (المادة 6)، وتحظر **إفشاء المعلومات السرية حتى بعد انتهاء الخدمة** (المادة 15).","لذلك فأي طلب للمعلومات من جهة خارجية، أو أي رغبة في نشر صور، تمر بإدارة المدرسة ولوائح الوزارة أولاً."],"pts":["نشر صور الطلاب: **مراجعة لوائح الوزارة أولاً**، ثم إذن ولي الأمر، والنشر عبر القنوات الرسمية.","طلب جهة خارجية (أخصائي، جهة بحثية) معلومات عن طالب: **إدارة المدرسة أولاً** واتباع تعليماتها.","المدونة تطلب **تجنب التصوير أو نشر أي محتوى يتعلق بالمدرسة أو الطلاب** في مواقع التواصل (المادة 21).","لا تُعرض كشوف الدرجات أو ترتيب الطلاب علناً."],"ex":["اتصل شخص يعرّف نفسه بأنه أخصائي ويطلب ملف طالب في الصف السادس. المعلمة تعتذر بلطف وتحيله إلى قائدة المدرسة، ولا ترسل شيئاً حتى لو أكد أن الطالب موافق."],"traps":[],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المواد 6 و 8 و 15 و 21)"},"ar.l02.mithaq":{"k":"أخلاقيات المهنة","t":["Teaching Ethics Charter","ميثاق أخلاقيات مهنة التعليم"],"aka":["ميثاق أخلاقيات مهنة التعليم","الميثاق","أخلاقيات المهنة","أهداف الميثاق"],"body":["ومكانته ثابتة في ثلاث وثائق رسمية حديثة: المعيار الفرعي 1.3 يطلب أن **يربط المعلم بين ما نصت عليه مواد ميثاق أخلاقيات مهنة التعليم وأدائه المهني مع طلابه وزملائه وأولياء الأمور ومجتمع المدرسة**؛ ولائحة الوظائف التعليمية تجعل **عدم النزاهة أو الإخلال بأمانة التعليم وعدم الالتزام بميثاقها** من حالات الإبعاد (المادة 14/8)؛ ونظام التعليم العام 1448 ينص على [[الالتزام بميثاق أخلاقيات مهنة التعليم|ar.law.ethics]] ضمن واجبات المعلم."],"pts":["علاقات المعلم في الميثاق (الطلاب، الزملاء، الأسرة، المجتمع) هي نفسها أبواب الواجبات في مدونة 1447.","**أهداف الميثاق**: تعزيز انتماء المعلم لرسالته ومهنته والارتقاء بها، توعيته بأهميته المهنية، **الإسهام في تعزيز مكانة المعلم العلمية والاجتماعية**، وحفزه على تمثّل قيم مهنته.","**مواده**: التعريفات ← الأهداف ← رسالة التعليم ← المعلم وأداؤه المهني ← المعلم وطلابه ← المعلم والمجتمع ← المعلم والمجتمع المدرسي ← المعلم والأسرة؛ و«المعلم» فيه يشمل المشرفين والمديرين والمرشدين، و«الطالب» طلاب التعليم العام وما في مستواه.","**المجتمع المدرسي**: الثقة المتبادلة والعمل **بروح الفريق** مع الزملاء والإدارة، واحترام [[قواعد السلوك الوظيفي|ar.l02.civilcode]]؛ والالتزام بالأنظمة والمشاركة في نشاطات المدرسة **أركان أساسية** في تحقيق أهدافها."],"ex":["معلمان اختلفا: هل يجوز ذكر أسماء الطلاب الضعاف أمام الصف لتحفيزهم؟ يرجعان إلى الميثاق (صون كرامة الطالب) ومدونة 1447 (السرية والعدالة)، فيتفقان على التغذية الراجعة الفردية."],"traps":["لا تقل «ألغت مدونة 1447 الميثاق»: نص المدونة لم يذكر ذلك، والمعايير ونظام 1448 ولائحة الوظائف ما زالت تسمّي الميثاق."],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (المعيار 1.3)؛ لائحة الوظائف التعليمية بتعديلات 1446هـ (المادة 14/8)؛ نظام التعليم العام 1448 (المادة 49/3)"},"ar.l02.code1447":{"k":"الأحدث","t":["Code of Conduct for Education Job Holders 1447","مدونة السلوك الوظيفي لشاغلي الوظائف التعليمية 1447"],"aka":["مدونة السلوك الوظيفي","مدونة 1447","المدونة"],"body":["أحدث وثيقة تنظم سلوك المعلم: **مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية**، صدرت عن وزارة التعليم بتاريخ **1447/2/3هـ**، استناداً إلى المادة 32 من لائحة الوظائف التعليمية التي كلفت الوزارة بإصدارها بالاتفاق مع الجهات المختصة.","تتكون من **26 مادة** في ستة أبواب وأحكام ختامية: أحكام تعريفية، ثم واجبات شاغل الوظيفة التعليمية، ثم المحظورات، ثم واجبات استخدام التقنية، ثم تعارض المصالح ومكافحة الفساد، ثم التزامات الوزارة تجاه المعلم."],"pts":["**المنبع الأساس** لسلوك المعلم: الآداب والأخلاق الإسلامية وفق توجيهات ولاة الأمر والأنظمة (المادة 2).","كل معلم **مسؤول عما يصدر عنه**، والمخالفة تعرّضه **للمساءلة والإجراءات التأديبية والجزائية** (المادتان 4 و 5).","مع الطلاب (المادة 8): العدالة دون تمييز، دعم ذوي الإعاقة، السرية، **عدم تكليفهم بطلبات مادية** للأنشطة أو الوسائل، الالتزام بلائحة تقويم الطلاب، و**الاطلاع والتقيد بنظام حماية الطفل ونظام الحماية من الإيذاء**.","مع الرؤساء (المادة 11): ينفذ المهام، وإذا كانت مخلة بالأنظمة **يُعلم رئيسه خطياً**.","تسري على جميع شاغلي الوظائف التعليمية بمختلف التصنيفات التعاقدية، وفي **المدارس الأهلية والعالمية** والمدارس والأكاديميات السعودية في الخارج (المادة 25)."],"ex":["طلب مسؤول من معلم تعديل درجات طالب دون سند. المعلم وفق المادة 11 يُعلم رئيسه **كتابياً** أن الطلب مخالف للأنظمة، ولا ينفذه، ولا ينشر الأمر خارج القنوات الرسمية."],"traps":["مدونة 1447 تسري على **المعلم في المدرسة الأهلية** أيضاً.","عند الأمر المخالف: لا تنفيذ صامت ولا رفض شفهي، بل **إعلام الرئيس خطياً**."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المواد 1–26)"},"ar.l02.prohibited":{"k":"مدونة 1447","t":["Prohibitions in the 1447 Code","محظورات المعلم وتعارض المصالح"],"aka":["المحظورات","تعارض المصالح","السرية المهنية"],"body":["الباب الثالث من مدونة 1447 يحدد ما لا يجوز للمعلم مطلقاً، ويكمله الباب الخامس عن تعارض المصالح ومكافحة الفساد. هذه «الخطوط الحمراء» المهنية."],"pts":["**عام** (المادة 14): الاستهزاء بشعائر الإسلام أو اعتناق الأفكار المتطرفة أو نشرها؛ إساءة استعمال السلطة؛ استغلال النفوذ؛ الرشوة؛ التزوير؛ **تسريب أسئلة الاختبار ونماذج الإجابة**؛ الاشتغال بالتجارة؛ الجمع بين الوظيفة ومهنة أخرى دون ترخيص؛ الإضراب أو التحريض عليه؛ الشكاوى الجماعية أو الكيدية؛ و**جمع الأموال لأي غرض من الطلبة والموظفين**.","**المعلومات** (المادة 15): إفشاء المعلومات السرية **حتى بعد انتهاء الخدمة**؛ والتصريح للإعلام أو وسائل التواصل في موضوعات تحت الدراسة أو التحقيق دون موافقة خطية مسبقة.","**الهدايا** (المادة 17): قبول هدية أو ميزة تؤثر في نزاهته أو قراراته.","**تعارض المصالح** (المادة 22): الإفصاح خطياً عن أي تعارض قبل اتخاذ القرار، وعدم المشاركة في قرار عقد يكون أحد أقاربه طرفاً فيه.","**مكافحة الفساد** (المادة 23): إبلاغ الرئيس المباشر خطياً عن أي تجاوز، وإبلاغ الجهات المختصة عن الفساد، وإعلام الرئيس فوراً إذا عُرضت عليه رشوة."],"ex":["ولي أمر يقدّم لمعلمة هدية ثمينة قبل اختبارات نهاية الفصل. تعتذر المعلمة بلطف؛ لأن المادة 17 تحظر قبول هدية من شأنها التأثير في نزاهتها أو قراراتها، والتوقيت يجعل التأثير محتملاً."],"traps":["جمع مبلغ من الطلاب «لحفلة الصف» أو «لوسائل تعليمية» **محظور** ولو كان يسيراً (المادتان 8 و 14).","سرية المعلومات **لا تنتهي** بانتهاء الخدمة."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المواد 14–17 و 22–23)"},"ar.l02.civilcode":{"k":"للتمييز","t":["Civil Service Code of Conduct","مدونة السلوك الوظيفي للوظيفة العامة"],"aka":["قواعد السلوك الوظيفي","مدونة الوظيفة العامة"],"body":["قبل مدونة المعلمين توجد **مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة العامة**: إطار عام يجب على **كل موظف عام** التقيد به، تلقي الضوء على المعايير والأخلاق والقيم التي يتحلى بها الموظف أثناء أداء واجباته، وتُعد مخالفتها مخالفة لمقتضى الواجب الوظيفي يترتب عليها إجراءات تأديبية وجزائية.","ونصت مقدمتها على أنها تضمنت المبادئ العامة الشاملة، فقد لا تحيط بمعايير كل جهة، وقد يتطلب الأمر **إضافة معايير وقواعد تتناسب مع الجهات ذات الطابع الوظيفي أو المهني الخاص**. وهذا دور [[مدونة المعلمين 1447|ar.l02.code1447]]: تفصيل خاص بمهنة التعليم."],"pts":["**مدونة 1447**: لشاغلي الوظائف التعليمية في الحكومي والأهلي والعالمي والمدارس السعودية في الخارج، وفيها ما يخص الطلاب وأولياء الأمور والاختبارات.","العلاقة تكاملية: المعلم موظف عام، وصاحب مهنة لها قواعدها الخاصة."],"ex":["معلم يسأل عن استعمال جهاز حاسب المدرسة في عمل خاص خارج الدوام. المبدأ العام في مدونة الوظيفة العامة، ومنصوص أيضاً لشاغلي الوظائف التعليمية في مدونة 1447: يُحظر استخدام ممتلكات الدولة لمنفعة شخصية (المادة 16)، ولا يُستخدم الجهاز إلا لأغراض العمل (المادة 18)."],"traps":[],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة العامة (المقدمة)؛ مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ"},"ar.l02.jobsreg":{"k":"لائحة","t":["Education Jobs Regulation","لائحة الوظائف التعليمية (بتعديلات 1446)"],"aka":["لائحة الوظائف التعليمية","رتب المعلمين","تحت التجربة سنتين"],"body":["اللائحة تنظم المسار الوظيفي للمعلم: الرتب، والتعيين، والتجربة، والنصاب، والترقية، والنقل، والتكليف، والرواتب، وانتهاء الخدمة. وتقع في **11 باباً و 38 مادة**، وحلّت محل لائحة الوظائف التعليمية السابقة الصادرة عام 1401هـ. والنسخة المعتمدة هنا **المتضمنة تعديلات 1446هـ**."],"pts":["**التعيين ابتداءً** على **معلم ممارس** (شهادة جامعية في التخصص مع تحقيق المعايير المهنية) أو **مساعد معلم** (ثانوية ودبلوم لا يقل عن سنة) (المادة 5).","**التجربة سنتان** للمعين ابتداءً، وإن لم تثبت صلاحيته يصدر الوزير قراراً بإنهاء خدمته (المادة 8).","**الإبعاد** عن التدريس (المادة 14) في حالات منها: الإساءة للدين، تبني اتجاهات فكرية منحرفة، الإيذاء الجسدي أو التحرش، المخدرات، و**عدم النزاهة أو الإخلال بأمانة التعليم وعدم الالتزام بميثاقها**.","**التكليف** (المادة 19): القائد والوكيل من رتبة ممارس فأعلى، والمشرف التربوي من متقدم أو خبير؛ ومدة التكليف لا تزيد على أربع سنوات قابلة للتمديد."],"ex":["خريجة بكالوريوس تربوي عُيّنت معلمة ممارسة: تبدأ على الدرجة الثانية من المستوى الأول، وتقضي سنتين تحت التجربة، ثم تحتاج 6 سنوات في الرتبة مع بقية الشروط لتُرقّى إلى معلمة متقدمة."],"traps":["قائد المدرسة يُختار من المكلفين بعمل **وكيل** مضى على تكليفهم 3 سنوات على الأقل (المادة 19/3)."],"src":"لائحة الوظائف التعليمية بتعديلات 1446هـ (المواد 1–38)؛ مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المقدمة)"},"ar.l02.license":{"k":"الرخصة","t":["Professional License","الرخصة المهنية"],"aka":["الرخصة المهنية","درجات الاجتياز","صلاحية الرخصة","إلزامية لمزاولة التعليم"],"body":["الرخصة المهنية **وثيقة تصدرها هيئة تقويم التعليم والتدريب** وفق معايير وإجراءات محددة، يكون حاملها مؤهلاً لمزاولة مهنة التعليم بحسب مستويات محددة ومدة زمنية محددة. والوزارة تلتزم بنتائج اختبارات الكفاية المهنية والرخص الصادرة من الهيئة (لائحة الوظائف، المادة 32)."],"pts":["**خبرة مستوى خبير**: 11 سنة فأكثر للبكالوريوس، و 9 للماجستير، و 7 للدكتوراه؛ و**متقدم**: من 6 للبكالوريوس، ومن 5 للماجستير، ومن 4 للدكتوراه.","**السريان**: إذا صدرت الرخصة خلال سنة ميلادية من اجتياز الاختبار الأحدث فمدتها **5 سنوات من تاريخ إصدارها**؛ وإن صدرت بعد ذلك تنتهي بعد 5 سنوات من نهاية تلك السنة.","**تعديل 1446** (المادة 34 من اللائحة): الرخصة **شرط للممارسة المهنية**، ويجب الحصول عليها قبل **2026/02/01م**، ويُستثنى من بلغ **الخمسين** قبل هذا التاريخ مع إلحاقه ببرامج تطوير مهني."],"ex":["معلم بكالوريوس خبرته 8 سنوات حصل على 82 في التربوي و 85 في التخصصي. درجاته تؤهل لخبير، لكن خبرته (من 6 إلى أقل من 11) تجعل رخصته **متقدم**، ويرقّيها حين يكمل 11 سنة."],"traps":[],"src":"ضوابط الرخص المهنية للوظائف التعليمية، هيئة تقويم التعليم والتدريب (1445هـ، المواد 1–9)؛ لائحة الوظائف التعليمية بتعديلات 1446هـ (المواد 1 و 32 و 34)"},"ar.l02.behavior":{"k":"قواعد 1447","t":["Behavior & Attendance Rules 1447","قواعد السلوك والمواظبة (الإصدار الخامس)"],"aka":["قواعد السلوك والمواظبة","لائحة السلوك والمواظبة"],"body":["قواعد السلوك والمواظبة لطلبة التعليم العام في **إصدارها الخامس (1447هـ - 2025م)** هي المرجع الحالي لضبط سلوك الطلاب وحضورهم، وتلغي ما سبقها. هدفها العام: **ضبط السلوك والمواظبة بما يتوافق مع المبادئ الإسلامية والقيم الأخلاقية وثقافة المجتمع**.","وتحدد أدوار كل طرف: قسم التوجيه الطلابي بإدارة التعليم، وإدارة المدرسة، والمعلم، ولجنة التوجيه الطلابي، والموجه الطلابي، والأسرة، والطالب."],"pts":["تُطبق في مدارس التعليم العام **الحكومي والخاص** ومدارس التعليم المستمر والمدارس السعودية في الخارج (المادة 28/1).","**دور المعلم**: تنفيذ الإجراءات الثلاثة الأولى لمشكلات **الدرجة الأولى** مباشرة وإحالة من لم يتجاوب لإدارة المدرسة، ورصد مشكلات **الدرجة الثانية فأعلى** وتسليمها للإدارة، وتمكين الطالب من **الفرص التعويضية**.","مثال من الدرجة الثالثة (المتوسطة والثانوية): **الشجار أو الاشتراك في مضاربة جماعية**؛ الإجراء الأول دعوة ولي الأمر وتعهد خطي وحسم 3 درجات وتحويل الطالب للموجه الطلابي، والثاني عند التكرار يشمل **نقل الطالب إلى فصل آخر** بقرار لجنة التوجيه الطلابي (المادة 12)."],"ex":[],"traps":[],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ (المواد 2 و 3 و 12 و 28)"},"ar.l02.committee":{"k":"قواعد 1447","t":["Student Guidance Committee & Counselor","لجنة التوجيه الطلابي والموجه الطلابي"],"aka":["لجنة التوجيه الطلابي","الموجه الطلابي","المرشد الطلابي","لجنة التوجيه والإرشاد"],"body":[],"pts":["من مهام اللجنة: إعداد خطة لتفعيل القواعد، **عقد مجلس أولياء الأمور** للتأكيد على دور الأسرة، استلام شواهد السلوك المتميز وتقدير الدرجة، توفير فرص التعويض، **تصنيف المشكلات التي لم ترد في القواعد** بما لا يتجاوز الدرجة الثالثة، دراسة **الحالات عالية الخطورة** ورفع التوصيات لمدير المدرسة، وإحالة الحالات للجهات المختصة.","المعلم يحدد أبرز مشكلات الطلبة ويطلب **الدعم والمشورة من لجنة التوجيه الطلابي** عند الحاجة، ويشارك في متابعة الحالات داخل الفصل وتنفيذ توصياتها."],"ex":["معلم لاحظ أن طالباً يتأخر صباحاً ويبدو منهكاً. لا يكتفي بالحسم، بل يحيل الحالة للموجه الطلابي ليدرس السبب مع الأسرة، فيتبين أن الطالب يرعى أخاه المريض ليلاً، فتُبنى له خطة دعم."],"traps":["خيار «الموجه الطلابي يحسم الدرجة» خاطئ؛ الحسم من **إدارة المدرسة**.","الحالات **عالية الخطورة** تتطلب تدخلاً مباشراً وسريعاً من إدارة المدرسة."],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ (التعريفات، دور لجنة التوجيه الطلابي، دور المعلم، المادتان 5 و 28)"},"ar.l02.childprot":{"k":"نظام","t":["Child Protection Law","نظام حماية الطفل ولائحته"],"aka":["نظام حماية الطفل","الإيذاء","الإهمال","1919"],"body":["نظام حماية الطفل صدر بالمرسوم الملكي **م/14 وتاريخ 1436/2/3هـ**، وعُدّل بالمرسوم **م/72 وتاريخ 1443/8/6هـ**، وصدرت له **لائحة تنفيذية جديدة** بديلة عن لائحة 1436. يعرّف **الطفل** بأنه كل إنسان **لم يتجاوز الثامنة عشرة**، ويحميه من **الإيذاء** (كل شكل من أشكال الإساءة للطفل أو استغلاله أو التهديد بذلك: جسدية أو نفسية أو جنسية) ومن **الإهمال** (عدم توفير حاجاته الأساسية أو التقصير فيها: الجسدية والصحية والعاطفية والنفسية والتربوية والتعليمية وغيرها).","ومدونة 1447 تلزم المعلم **بالاطلاع على اللائحة التنفيذية لنظام حماية الطفل ونظام الحماية من الإيذاء والتقيد بهما** في ممارساته التربوية (المادة 8)."],"pts":["**واجب الإبلاغ**: على كل من يطّلع على حالة إيذاء أو إهمال تبليغ الجهات المختصة **فوراً** (النظام، المادة 22).","اللائحة التنفيذية الجديدة (المادة 21): الإبلاغ إلى **مركز البلاغات على الرقم الموحد** مع **المحافظة على سرية هوية المبلّغ**؛ وعلى إدارة المدرسة إذا تعذر حل الحالة أن تبلّغ مركز البلاغات مع تقرير، وتسهّل دخول فريق متعدد التخصصات، وتبلّغ الجهات الأمنية في الحالات الخطيرة.","من صور الإيذاء أو الإهمال في النظام (المادة 3): **التسبب في انقطاع الطفل عن التعليم**، و**استخدام الكلمات المسيئة التي تحط من كرامته**، و**التمييز ضده**.","ونظام التعليم العام 1448 يضيف [[واجب الإبلاغ على إدارة المؤسسة التعليمية|ar.law.report]]."],"ex":[],"traps":["الكلمات المسيئة التي تحط من كرامة الطفل **إيذاء** في نص النظام، لا «أسلوب حازم»."],"src":"نظام حماية الطفل (م/14 لعام 1436، وتعديلات م/72 لعام 1443)؛ اللائحة التنفيذية الجديدة لنظام حماية الطفل (المادة 21)؛ قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ (المادة 29)؛ مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادة 8)"},"ar.l02.rifq":{"k":"برنامج وزاري","t":["Rifq Program","برنامج رفق لخفض العنف (1445)"],"aka":["رفق","التنمر","العنف"],"body":["«رفق» برنامج إرشادي وقائي وعلاجي أعدته وزارة التعليم (التوجيه الطلابي) عام 1445هـ لخفض العنف المدرسي بكل أشكاله، طوال العام الدراسي وفي جميع المراحل، بنين وبنات. واسمه مأخوذ من الحديث: «إن الرفق لا يكون في شيء إلا زانه، ولا يُنزع من شيء إلا شانه»، و«الرفق» في البرنامج ضد العنف ومعناه لين الجانب.","يعمل على ثلاثة مستويات: **المدرسة** و**الأسرة** و**الطلبة**، ويرتب العمل في: وقاية، ثم كشف وتعرّف على المؤشرات (المشاهدة الواعية، الملاحظة العلمية، قائمة المؤشرات)، ثم تدخل مبكر، ثم أساليب علاجية للمعتدي والمعتدى عليه، مع نماذج للحصر والمتابعة والإبلاغ لمركز البلاغات."],"pts":["**العنف**: كل سلوك متعمد ينتج عنه أضرار جسدية أو نفسية للآخرين أو تخريب للممتلكات.","**التنمر** خمسة محددات: شكل من أشكال العنف، **متعمد**، بين **أقران** من الفئة العمرية نفسها، مع **اختلاف ميزان القوة**، و**متكرر**.","**المشاجرة الطارئة ليست تنمراً**، لغياب شرط التكرار والاستمرار.","النظريات المفسرة للعنف في البرنامج: البيولوجية، والسلوكية (التعزيز)، و**التعلم بالمشاهدة (النمذجة)**، و**الإحباط - العدوان**، والاجتماعية.","من استراتيجيات الخفض **ضبط المثيرات**: الحد من أسباب العنف في المحيط التربوي والأسري."],"ex":["طالبان في الخامس الابتدائي تشاجرا مرة واحدة على الكرة: مشاجرة طارئة تُعالج بإجراءات السلوك. أما طالب يسخر يومياً من زميل أصغر جسماً ويعزله عن المجموعة منذ أسابيع، فهذا **تنمر** لاكتمال محدداته، ويستدعي خطة علاجية مع الموجه الطلابي وإشراك الأسرة."],"traps":["لا يكفي **التكرار** وحده؛ التنمر يحتاج **تعمداً واختلال قوة بين أقران**."],"src":"برنامج رفق لخفض العنف في مدارس التعليم العام، وزارة التعليم 1445هـ (الملخص، الأهداف، المصطلحات، النظريات المفسرة، أسباب العنف)"},"ar.l03.pd":{"k":"مفهوم","t":["Professional Development","التنمية المهنية للمعلم"],"aka":["التنمية المهنية","التطوير المهني","النمو المهني"],"body":["التنمية المهنية جهد منظم مستمر يرتقي بمعارف المعلم ومهاراته وقيمه حتى ينعكس على تعلم طلابه. وتعرّف لائحة الوظائف التعليمية **التطوير المهني** بأنه **عملية منظمة لتنمية المعارف والمهارات العلمية والتربوية وفق المعايير المهنية**.","وهو اليوم حق وواجب ومعيار ترقية: مدونة 1447 تطلب أن **يحرص المعلم على التطوير المهني المستمر واستخدام أساليب التدريس الفعالة والمبتكرة** (المادة 7)، ونظام التعليم 1448 يجعله [[حقاً وواجباً|ar.law.teacher]]، ولائحة الوظائف تشترط **الحد الأدنى من نقاط التطوير المهني** للترقية والتكليف."],"pts":["مكوناتها في الأدب التربوي: **التدريب المهني** (مهارات) + **التربية المهنية** (معتقدات وقيم) + **المساندة المهنية** (استقرار وظيفي ومناخ داعم).","مبادئها: **عملية مستمرة** لا نتيجة تنتهي بدورة، تُخطط جماعياً، في بيئة مشجعة، ويُقاس **أثرها في تعلم الطلاب**.","أهدافها: مواكبة المستجدات، التعلم مدى الحياة، ترسيخ أخلاقيات المهنة، تحسين تعلم الطلاب.","المعلم يتحمل **مسؤولية نموه الذاتي**، ويدرس مناسبة أي دورة له قبل التسجيل."],"ex":["عُرضت على معلم دورة في تصميم الفيديو التعليمي. قبل التسجيل سأل: هل تعالج احتياجاً في خطتي؟ هل ستغير ممارستي مع طلابي؟ فوجد أن احتياجه الأكبر في التقويم التكويني، فقدّمه في خطته."],"traps":["**تطوير البيئة المادية للصف** ليس هدفاً للتنمية المهنية.","**المساندة** ليست تدريباً؛ هي الاستقرار الوظيفي والمناخ الداعم."],"src":"لائحة الوظائف التعليمية بتعديلات 1446هـ (المادتان 1 و 10)؛ مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادة 7)؛ نظام التعليم العام 1448 (المادتان 48 و 49)"},"ar.l03.reflect":{"k":"التأمل","t":["Reflective Practice","التأمل الذاتي في التدريس"],"aka":["التأمل الذاتي","التأمل في التدريس","التأمل الناقد","التأمل الذاتي وتقويم الزملاء والخبراء"],"body":["التأمل الذاتي استقصاء منظم وواعٍ في الممارسة: يعود المعلم إلى ما فعله، ويسأل لماذا حدث، وما البديل، ثم يجرب. وارتبط المفهوم بأعمال دونالد شون (Donald Schön) عن «الممارس المتأمل» الذي يتأمل **أثناء الفعل** و**بعد الفعل**.","مؤشر الممارس 2.2 يطلب أن **يحلل ممارساته المهنية تحليلاً نقدياً في ضوء التقويم والتأمل الذاتي ومستوى أداء طلابه**، ومؤشر 3.1 يطلب أن **يمارس التأمل الذاتي للواقع التدريسي لاستكشاف القضايا التربوية التي تمثل مجالاً للبحوث الإجرائية**."],"pts":["**أدوات فردية**: [[نافذة جوهاري|ar.l03.johari]]، أداة سوات SWOT، بطاقة التأمل، ملف الإنجاز، تصوير الدرس بالفيديو، صحائف التأمل، سلالم التقدير وقوائم الشطب.","**أدوات جماعية**: البحث الإجرائي، ملف الإنجاز الجماعي، مؤتمرات التأمل، مجموعات التركيز، التدريب المعرفي.","أسئلة توجّه تأمل الطالب في تعلمه: ماذا تعلمت؟ كيف أحسّن؟ وليس «كيف أتفوق على زملائي؟» (مقارنة لا تأمل)."],"ex":[],"traps":[],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (2.2 و 3.1)؛ أدبيات الممارس المتأمل (دونالد شون)"},"ar.l03.johari":{"k":"أداة تأمل","t":["Johari Window","نافذة جوهاري"],"aka":["نافذة جوهاري"],"body":["أداة لفهم الذات وعلاقتها بالآخرين، وضعها عالما النفس جوزيف لفت وهارينغتون إنغام (Joseph Luft & Harrington Ingham)، واسمها مركب من اسميهما. تقسم ما يُعرف عن الشخص إلى أربع مناطق بحسب سؤالين: هل أعرفه أنا؟ وهل يعرفه الآخرون؟"],"pts":["**المنطقة العامة (المفتوحة)**: أعرفها ويعرفها غيري.","**المنطقة العمياء**: يعرفها غيري ولا أعرفها، وتُضيَّق **بطلب التغذية الراجعة**.","**المنطقة الخاصة (المخفية)**: أعرفها وأخفيها، وتضيق **بالإفصاح**.","**المنطقة المجهولة**: لا أعرفها ولا يعرفها غيري، وتُكتشف بالتجربة والتأمل.","الهدف المهني: **توسيع المنطقة العامة**."],"ex":["معلم يظن أنه يوزع الأسئلة على الجميع، وبعد زيارة زميل اكتشف أنه يوجه أغلبها للصفوف الأمامية. هذه معلومة كانت في **المنطقة العمياء**، وكشفتها التغذية الراجعة."],"traps":["ما يراه الآخرون ولا تراه = **العمياء** لا الخاصة.","علاج العمياء **التغذية الراجعة**، وعلاج الخاصة **الإفصاح**."],"src":"نافذة جوهاري (لفت وإنغام)"},"ar.l04.plc":{"k":"مجتمعات التعلم","t":["Professional Learning Community","مجتمع التعلم المهني"],"aka":["مجتمع التعلم المهني","مجتمعات التعلم المهنية","مجتمعات التعلم","ثقافة التعاون","الأسئلة والفصول"],"body":["مجتمع التعلم المهني مجموعة من المعلمين داخل المدرسة يعملون معاً بشكل **مخطط ومستمر** لتحسين تعلم الطلاب، فيتعلمون هم أنفسهم أثناء ذلك. وارتبط المفهوم في الأدب التربوي بأعمال ريتشارد دوفور (Richard DuFour) الذي لخّصه في ثلاث أفكار كبرى: ضمان تعلم الطلاب، وثقافة التعاون، والتركيز على النتائج.","وفي الميدان السعودي ينص النموذج الإشرافي في ضوء تمكين المدرسة 1446 من أهدافه على **توفير متطلبات التطوير المهني المستمر الذاتي والتعاوني، وتفعيل مجتمعات التعلم المهنية بأساليب وأدوات وأوعية متنوعة**، ويظهر في نموذج تقييم أداء المعلم ضمن عنصر «التفاعل مع المجتمع المهني»."],"pts":["**عوامل النجاح**: قيادة داعمة، وبنية تنظيمية ووقت مخصص، ونظام فاعل للتطبيق.","تحليل نتائج الاختبارات الوطنية لثلاث سنوات يُوظَّف في **تعديل خطط التدريس والأنشطة في ضوء النتائج**؛ ومراجعة الزملاء لأعمال بعضهم تساعد على **حل مشكلات التدريس**."],"ex":["معلمو العلوم في الصف الثاني المتوسط يجتمعون كل أسبوعين. حللوا سؤالاً أخفق فيه أكثر من نصف الطلاب في الفصول الأربعة، فاكتشفوا أن المفهوم يُدرّس بمثال واحد، فاتفقوا على نشاط عملي موحد، وسيقيسون أثره في الاختبار القصير القادم."],"traps":[],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (3.1)؛ النموذج الإشرافي في ضوء تمكين المدرسة 1446 (الأهداف التفصيلية)؛ الدليل الإرشادي لإدارة الأداء الوظيفي 2026؛ أدبيات مجتمعات التعلم المهنية (دوفور)"},"ar.l04.plcforms":{"k":"مجتمعات التعلم","t":["Forms of Collaborative Learning","أوعية مجتمعات التعلم المهنية"],"aka":["أوعية مجتمعات التعلم","أوعية مجتمعات التعلم المهنية","التوأمة المهنية","الشبكات المهنية","التدريب بالأقران"],"body":["«الأوعية» هي القوالب التي يجري فيها تعلم المعلمين معاً. واختيار الوعاء يتبع الهدف: مهارة جديدة؟ مشكلة صفية مشتركة؟ تبادل بين مدرستين؟","وتجمعها قائمة واحدة: التدريب المباشر، ورش العمل وحلقات النقاش، المؤتمرات والندوات، البرامج الأكاديمية، البحوث الإجرائية، التدريب بالأقران، التوأمة المهنية، الشبكات المهنية، مجموعات التخصص."],"pts":["**التدريب بالأقران**: زميل يدرب زميله على مهارة ويتابعه في الصف.","**التوأمة المهنية**: شراكة بين معلمين أو مدرستين لتبادل الخبرات.","**الشبكات المهنية**: روابط معلمين متميزين في مهارة، ينسق المشرف عملهم لدعم أقرانهم."],"ex":["مدرستان متجاورتان: الأولى متميزة في التعلم التعاوني والثانية في توظيف التقنية. اتفقتا على توأمة: زيارات متبادلة شهرية، وورشة مشتركة كل فصل."],"traps":["التوأمة **بين طرفين** (معلمين أو مدرستين)؛ والشبكة **مجموعة أوسع** ينسقها مشرف."],"src":"أدبيات مجتمعات التعلم المهنية؛ النموذج الإشرافي في ضوء تمكين المدرسة 1446"},"ar.l04.parentcomm":{"k":"أولياء الأمور","t":["Communicating with Parents","التواصل مع أولياء الأمور"],"aka":["التواصل مع أولياء الأمور","شريك الوالدين","اجتماع الأهداف المشتركة"],"body":["العلاقة مع ولي الأمر شراكة في مصلحة الطالب. ومدونة 1447 تحدد قواعدها في المادة 9: **تعزيز التواصل الإيجابي** والاستماع إلى ملاحظاتهم والإجابة عن استفساراتهم في الزيارات المدرسية أو **عبر المنصات الرسمية المعتمدة للتواصل مع ولي الأمر**، والتعامل **باحترام وتقدير** وتقديم المعلومات عن المستوى الأكاديمي والسلوكي **بأسلوب واضح وموضوعي ودون تمييز**، وتجنب ما يثير سوء الفهم أو النزاع، والتعاون في إيجاد الحلول وإرشاد الأسرة إلى الأساليب التربوية."],"pts":["التواصل لا يقتصر على المشكلات: **رسائل إيجابية** ودعوات للفعاليات والتكريم.","مع أسر الطلاب **ذوي الإعاقة**: توجيه وتوعية لتعديل الاتجاهات السلوكية الخاطئة وتوثيق الروابط بين البيت والمدرسة (المادة 9/3).","**السرية**: معلومات الطالب تخصه وأسرته؛ ولا يُتحدث عن طالب أمام غيره.","نموذج تقييم أداء المعلم يخصص **10%** لعنصر **التفاعل مع أولياء الأمور**."],"ex":["معلمة ترسل كل أسبوعين رسالة قصيرة عبر المنصة المعتمدة: إنجاز إيجابي للطالبة، ومهارة تعمل عليها، ونشاط منزلي من خمس دقائق. وحين احتاجت لاحقاً إلى لقاء بسبب تراجع مفاجئ، كانت الثقة قائمة."],"traps":["القناة **الرسمية المعتمدة** مقدمة على الحسابات الشخصية."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادة 9)؛ الدليل الإرشادي لإدارة الأداء الوظيفي 2026؛ المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (3.2)"},"ar.l04.angry":{"k":"موقف صفي","t":["The Upset Parent","ولي الأمر الغاضب والإنصات الفعّال"],"aka":["الإنصات الفعّال","الإنصات أولاً"],"body":[],"pts":["**الترتيب**: إنصات ← تلخيص ما فهمته منه ← عرض الحقائق بهدوء وموضوعية ← حل مشترك ← متابعة."],"ex":["ولي أمر يقول بحدة: «ابني يقول إنك تظلمه في الدرجات!». يدعوه المعلم للجلوس ويقول: «أفهم قلقك، أخبرني ماذا قال لك بالتفصيل»، وبعد أن ينتهي يعرض أوراق الطالب ومعايير التصحيح، ثم يتفقان على خطة مراجعة أسبوعية."],"traps":[],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادة 9)؛ المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (3.2)"},"ar.l04.family":{"k":"قواعد 1447","t":["The Family's Role","دور الأسرة ومجلس أولياء الأمور"],"aka":["دور الأسرة","مجلس أولياء الأمور","مجالس أولياء الأمور"],"body":[],"pts":["من أدوار الأسرة: **الاطلاع على جميع أنظمة المدرسة وقواعدها وتعليماتها ومناقشتها مع الأبناء**.","**إخطار المدرسة باحتياجات الابن** والتعاون معها لحل مشكلاته، و**إبلاغ الموجه الطلابي أو الوكيل** عند تعرضه لمشكلات سلوكية.","التزام ولي الأمر بمسؤوليته الكاملة تجاه ابنه وفق القواعد ونظامي **الحماية من الإيذاء وحماية الطفل**."],"ex":[],"traps":[],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ (دور الأسرة، دور لجنة التوجيه الطلابي)"},"ar.l04.partnership":{"k":"المجتمع المحلي","t":["Community Partnership","الشراكة المجتمعية"],"aka":["الشراكة المجتمعية","المشاركة المجتمعية","مقومات الشراكة"],"body":["ومن الأطر المشهورة في هذا الباب نموذج جويس إبستين (Joyce Epstein) لأنماط مشاركة الأسرة والمجتمع الستة: الوالدية، والتواصل، والتطوع، والتعلم في المنزل، والمشاركة في اتخاذ القرار، والتعاون مع المجتمع."],"pts":["مؤشر الممارس 3.3: **يوضح جوانب علاقة المدرسة مع المجتمع المحلي وأهميتها، ويشارك بإيجابية في المناسبات والفعاليات الاجتماعية التي تعززها**.","من صور التفاعل مع المؤسسات: تنمية الوعي بخدمة البيئة، التدريب في مراكز محو الأمية، دعم نادي الحي، دروس التقوية.","معلم يتتبع الفعاليات المحلية والدولية ويحث أولياء الأمور على المشاركة بمنجزات أبنائهم: يعكس **رغبته في دعم طلابه للافتخار بمنجزاتهم**."],"ex":["مركز صحي قريب يقدم للمدرسة محاضرة عن التغذية، والمدرسة تفتح ساحتها لحملة توعوية للحي. علاقة تبادلية واضحة، وكلاهما يخدم الصحة المدرسية."],"traps":["الشراكة **تبادلية**؛ الخيار الذي «يأخذ دعماً فقط» ناقص.","**المشاركة** جهود تطوعية في التخطيط والتنفيذ والتقويم؛ و**الشراكة** علاقة منظمة أوسع بمسؤولية مشتركة."],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (3.3)؛ رؤية المملكة 2030 (الشراكة المجتمعية)؛ أدبيات الشراكة بين المدرسة والأسرة والمجتمع (إبستين)"},"ar.l04.local":{"k":"مؤشر 3.3","t":["Local Issues & Functional Knowledge","القضايا المحلية ووظيفة المعرفة"],"aka":["القضايا المحلية","وظيفة المعرفة","القضية المحلية"],"body":[],"pts":["مدونة 1447: **مراعاة القيم المجتمعية في تقديم المحتوى التعليمي والتوعوي الهادف، مع تجنب المعلومات المضللة** (المادة 10).","مؤشر المتقدم: **يحلل القضايا المحلية التي ينبغي تناولها في المنهج ويبين لزملائه كيفية عرضها**.","**أمثلة قضايا محلية**: ترشيد المياه والكهرباء، السلامة المرورية، النظافة والتشجير، التصحر، التغذية والسمنة، التنمر الإلكتروني، الحفاظ على التراث، الإسراف في المناسبات."],"ex":[],"traps":[],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (المجال الأول: القيم والمسؤوليات المهنية) (3.3)؛ مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادة 10)"},"ar.l06.place":{"k":"الأعداد","t":["Place Value & Rounding","القيمة المنزلية والتقريب"],"pts":["**منازل العدد** من اليمين: آحاد، عشرات، مئات، آحاد الألوف، عشرات الألوف، مئات الألوف، آحاد الملايين؛ في 2571315 الرقم 5 الأيسر في **مئات الألوف**.","**الترتيب** التصاعدي من الأصغر: قارن العشرية منزلة منزلة (0.405 < 0.45 < 0.5 < 0.6).","**التقدير**: قرّب ثم احسب (0.4 جرام × 1000 دبوس ≈ 400 جرام)."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 4.4"},"ar.l06.div":{"k":"الأعداد","t":["Divisibility, Primes, GCD & LCM","قابلية القسمة والأولية والقاسم والمضاعف"],"pts":["**قابلية القسمة**: على 2 إذا كان الآحاد زوجياً، على 3 إذا قبل **مجموع الأرقام** القسمة على 3، على 5 إذا انتهى بـ 0 أو 5، على 6 إذا قبل 2 و 3، على 10 إذا انتهى بـ 0.","فردي + فردي = **زوجي**، وفردي + زوجي = فردي."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 4.4"},"ar.l06.frac":{"k":"الأعداد","t":["Fractions, Decimals & Equations","الكسور والعشرية والمعادلة"],"pts":["**الكسور الشائعة**: 1/2 = 50%، 1/4 = 25%، 3/4 = 75%، 1/5 = 20%، 1/8 = 12.5%، 1/3 ≈ 33.3%، 1/10 = 10%.","**ضرب العشري**: اضرب بلا فاصلة ثم ضعها بعدد المنازل في العددين (1.5 × 2.3 = 3.45)؛ و**القسمة** على عشري: انقل الفاصلة في الطرفين حتى يصير المقسوم عليه صحيحاً."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 4.4"},"ar.l07.principles":{"k":"مبادئ النمو","t":["Principles of Development","خصائص النمو ومبادئه"],"body":["وعلم نفس النمو يدرس **السلوك وتطوره** ويفيد في **ملاءمة التدريس للمرحلة**."],"pts":["عوامله: **تفاعل الوراثة والبيئة**، و**النضج** والتعلم والغدد والتغذية والأسرة.","مسك القلم نمو **جسمي (حركي دقيق)**، وتكوين المفاهيم **عقلي**، والتحكم بالغضب **انفعالي**."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1"},"ar.l07.stages":{"k":"المراحل الدراسية","t":["School-Age Characteristics","خصائص المراحل الدراسية"],"pts":["**الطفولة المتوسطة (6–9، الصفوف الأولية)**: نمو جسمي **بطيء منتظم**.","**الطفولة المتأخرة (9–12، الصفوف العليا)**: **سن الجماعة/العصابة**، بطء جسمي قبل طفرة المراهقة.","**المراهقة المبكرة (12–15، المتوسطة)**: البحث عن القدوة.","**المراهقة المتوسطة (15–18، الثانوية)**: الاستقلال عن الأسرة، الاهتمام بالمهنة، المثالية والمجادلة، الشعور بالذات ومقاومة السلطة.","الطفل الذي **يرمي الأشياء ويجربها** يمارس **الاستكشاف**."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.1"},"ar.l07.emo":{"k":"الحماية","t":["Emotional Disorders, Abuse & Neglect","الاضطراب الانفعالي والإيذاء والإهمال"],"body":[],"pts":["**مؤشرات اضطراب انفعالي**: حزن مستمر، انسحاب، نوبات غضب أو عدوان، خوف مفرط، شكاوى جسمية بلا سبب طبي، تغير حاد في النوم أو الأكل أو التحصيل.","علامات محتملة: **جسدي** (كدمات أو حروق غير مفسرة، خوف من العودة إلى المنزل)، **نفسي** (خوف شديد، تدنٍّ حاد في تقدير الذات)، **إهمال** (جوع مستمر، رداءة النظافة، غياب، حاجات صحية مهملة).","تعد القواعد **انقطاع الطالب عن التعليم** نوعاً من الإيذاء أو الإهمال، وتستثني المتعرض للإيذاء من إجراءات تهدد سلامته."],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ، المادة 29"},"ar.l08.styles":{"k":"أنماط التعلم","t":["Learning Styles & Models","أنماط التعلم ونماذجها"],"pts":["**هيرمان** يصنف التفكير في أربعة أرباع: تحليلي، منظم، شعوري اجتماعي، تخيّلي."],"ex":[],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.2"},"ar.l08.ld2":{"k":"صعوبات التعلم","t":["Diagnosing & Teaching LD","تشخيص صعوبات التعلم وتدريسها"],"pts":["و**الصعوبات الأولية** خلل في العمليات النفسية نفسها، و**الثانوية** تنتج عن عوامل خارجية كسوء التعليم.","أدوات التشخيص: الملاحظة، المقابلة، دراسة الحالة، الاختبارات محكية المرجع، و**الاختبارات التحصيلية والتشخيصية** مقارنةً بالقدرة، ومقياس **مايكل بست**.","**استراتيجيات تدريس ذوي الصعوبات**: التدريس المباشر، **تعدد الحواس (VAKT)**، استراتيجية **التجميع**، واستراتيجية **الموقع**."],"ex":["طالب ذكي في النقاش يقلب الحروف ويتعثر في القراءة: المعلم لا يصفه بالكسل، بل يوثق ملاحظاته ويحيله إلى معلم صعوبات التعلم."],"src":"الدليل التنظيمي للتربية الخاصة (وزارة التعليم)"},"ar.l08.sensory":{"k":"الفئات الخاصة","t":["Sensory & Physical Disabilities, ADHD","الإعاقات الحسية والجسمية وفرط الحركة"],"pts":["**الإعاقة السمعية**: لغة الإشارة وقراءة الشفاه، مواجهة الطالب، الجلوس في المقدمة، الوسائل البصرية.","**الإعاقة البصرية**: **برايل** والمواد المسموعة والمجسمات، والوصف اللفظي لما على السبورة.","**الإعاقة الجسمية**: قصور حركي أو حسي قد يصحبه قلق وعدم اتزان انفعالي؛ و**متلازمة داون** سببها كروموسومي.","مع أي فئة: **اعتراف بالإنجاز** ومهام في حدود القدرة وتعزيز فوري و**عدم** الإحراج أمام الأقران."],"src":"الدليل التنظيمي للتربية الخاصة (وزارة التعليم)"},"ar.l08.giftchar":{"k":"الموهوبون","t":["Gifted Traits & Provision","خصائص الموهوب ورعايته"],"pts":["خصائصه: نمو لغوي مبكر، فضول غير عادي، ذاكرة قوية، طلاقة لفظية، **حس الدعابة**، **قيادية**، نضج أخلاقي مبكر، **حساسية مفرطة** و**الكمالية**.","**التجميع**: فصول أو مجموعات خاصة؛ ويُفضّل في المملكة الإثراء داخل المدرسة مع برامج موهبة.","الخطأ: مزيد من **التمارين نفسها** أو جعله مساعداً للمعلم دائماً؛ والصحيح مهام أعمق."],"ex":[],"src":"القواعد التنظيمية لفصول ومدارس الموهوبين 1447هـ؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.4"},"ar.l08.bg":{"k":"الخلفيات","t":["Social, Economic & Cultural Backgrounds","الخلفيات الاجتماعية والاقتصادية والثقافية"],"body":[],"pts":["الإطار الوطني لمعايير المناهج: **تكافؤ فرص التعلم** يراعي الفروق و**الخلفيات الثقافية والاجتماعية** لكل الفئات.","التعرف على الخلفيات بالحوار وبطاقة الطالب والأسرة والموجه، مع حفظ **خصوصية** الظروف."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.2"},"ar.l08.iepteam":{"k":"التربية الخاصة","t":["IEP Team, Family & Placement","فريق الخطة ودور الأسرة والمكان التربوي"],"body":["مؤشر 5.4 للممارس: **يبين الإجراءات التي ينبغي التقيد بها في التعامل مع الفئات الخاصة، ويعرف الجهات التي يجب إشراكها في متابعة حالاتها**. والخطة في لائحة تقويم الطالب: وصف للخدمات التربوية والمساندة يعدها **فريق متعدد التخصصات**."],"pts":["المسار ينتهي بتحديد **الأهلية والمكان التربوي** ثم الخطة؛ والتشخيص **لا يُكتفى بنتيجة مقياس واحد**. و**لجنة الخطط التعليمية**: قائد المدرسة (رئيساً)، وكيل الشؤون التعليمية، **معلم التربية الخاصة**، **معلم التعليم العام**، المرشد أو الأخصائي الاجتماعي، **المختصون**، **ولي الأمر**، و**الطالب** قدر الإمكان.","**دور الأسرة**: الموافقة والمشاركة والتنفيذ في المنزل؛ و**على المدرسة** الشرح بلغة مفهومة والإشعار خطياً قبل أي تحويل."],"src":"الدليل التنظيمي للتربية الخاصة (وزارة التعليم)؛ لائحة تقويم الطالب وإجراءاتها"},"ar.l09.thorndike":{"k":"السلوكية","t":["Thorndike, Watson & Guthrie","ثورندايك وواطسون وجاثري"],"body":[],"pts":["**واطسون** مؤسس المدرسة السلوكية (الطفل ألبرت): الانفعالات تُتعلم بالإشراط، والبيئة تصنع الفرد.","**قانون المرة الواحدة**: ارتباط من خبرة واحدة شديدة (الخوف من النار بعد لسعة).","عند بافلوف أيضاً **الإشراط من الدرجة الثانية**."],"traps":[],"src":"Thorndike, Animal Intelligence؛ Watson (1913)؛ Guthrie (1935)"},"ar.l09.reinf":{"k":"السلوكية","t":["Reinforcers & Applications","المعززات وتطبيقات سكنر"],"pts":["**التسلسل**: ربط خطوات سلوك مركب؛ و**التلاشي**: سحب المساعدات تدريجياً.","**التعليم المبرمج**: خطوات صغيرة + استجابة نشطة + تغذية راجعة فورية + سير ذاتي؛ الخطي لسكنر والمتشعب لكراودر.","تطبيقات أخرى: **تعديل السلوك**، و**العقود السلوكية**، والتعلم للإتقان.","التعزيز **فوري** و**متنوع** و**متناسب**، للسلوك لا للشخص، ويتحول من مادي إلى اجتماعي إلى ذاتي."],"ex":[],"src":"Skinner, The Technology of Teaching"},"ar.l09.moraldis":{"k":"التعلم الاجتماعي","t":["Bandura — Moral Disengagement","الانفصال الأخلاقي والنمذجة في الصف"],"pts":["آليات **الانفصال الأخلاقي**: **التبرير الأخلاقي**، **التهذيب اللفظي** (الاعتداء «مزاح»)، **المقارنة المريحة**، **إزاحة المسؤولية**، **تشويه العواقب**، **لوم الضحية**."],"src":"Bandura, Moral Disengagement (2016)؛ Social Foundations of Thought and Action"},"ar.l09.tolman":{"k":"المعرفية","t":["Tolman & the Cognitive View","تولمان والمدخل المعرفي"],"body":[],"pts":["**تولمان** (الفئران في المتاهة): **التعلم الكامن** يحدث دون تعزيز ويظهر عند الحاجة، ويكوّن المتعلم **خرائط معرفية**؛ والتعلم **هادف**.","**أوزوبل – التعلم ذو المعنى بالاستقبال**: **الاندماج/الاحتواء** في البنية المعرفية؛ وأنماطه من (**استقبال/اكتشاف**) × (**ذو معنى/صمّ-استظهار**)، ولا يوجد «استقبال قائم على الاكتشاف».","**التمايز التقدمي**: الأفكار الشاملة أولاً؛ و**التوفيق التكاملي**: ربط الجديد بالسابق؛ وخرائط المفاهيم (نوفاك) من تطبيقاته.","**برونر – التعلم بالاكتشاف**: **بنية المادة**، والاستعداد، والدافعية الداخلية، و**الاكتشاف الموجه** الأنسب صفياً؛ و**العملي/الحركي** ← **الأيقوني/التصويري** ← **الرمزي**."],"src":"Tolman, Purposive Behavior in Animals and Men؛ Ausubel؛ Bruner"},"ar.l09.memtypes":{"k":"معالجة المعلومات","t":["Memory Types & Forgetting","أنواع الذاكرة والنسيان"],"pts":["الطويلة: **تقريرية** (دلالية: معانٍ؛ عرضية: أحداث شخصية) و**إجرائية** (مهارات كالسباحة).","**نظريات النسيان**: **الاضمحلال**، **التداخل** (**قبلي** و**بعدي**)، **الكبت**، فشل الاسترجاع."],"src":"Atkinson & Shiffrin (1968)؛ Tulving (1972)؛ Paivio"},"ar.l09.transfer":{"k":"السلوكية","t":["Transfer of Learning","انتقال أثر التعلم"],"body":["استخدام خبرة سابقة في موقف جديد. ويحققه التدريس للفهم لا للحفظ، وتنويع الأمثلة والسياقات، وربط التعلم بالحياة."],"pts":["**موجب** (القراءة تسهّل أي جملة)، **سالب** (عادة قديمة تعيق الجديد)، **صفري**.","**أفقي** (المستوى نفسه في سياق آخر) و**رأسي** (مهمة أعلى تبنى على السابقة)؛ و**قريب/بعيد**.","تفسيره: **العناصر المتطابقة** (ثورندايك) و**التعميم** (جد)."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.2 (أثر المعرفة السابقة في التعلم الحالي والمستقبلي)؛ دليل المتقدم للاختبار التربوي العام 1441، النموذج السابع"},"ar.l09.brain":{"k":"الدماغ","t":["Brain-Based Learning","التعلم المستند إلى الدماغ"],"body":[],"pts":["مبادئ (كين وكين): الدماغ **اجتماعي**، و**البحث عن المعنى** فطري بتكوين **الأنماط**، و**الانفعالات** أساسية، و**يتعزز بالتحدي ويُكبح بالتهديد**، وكل دماغ **فريد**، ويعالج **الأجزاء والكل معاً**.","في الصف: تقليل التهديد، ربط بخبرة الطالب، تنويع الحواس، فواصل وحركة، تعاون، تغذية راجعة فورية."],"src":"Caine & Caine, Making Connections؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.3"},"ar.l09.styles":{"k":"الأساليب المعرفية","t":["Cognitive Styles","الأساليب المعرفية"],"body":[],"pts":["**الاعتماد على المجال مقابل الاستقلال عنه** (ويتكن): **المعتمد** يدرك الكل ويتأثر بالسياق ويفضل العمل الجماعي، و**المستقل** يحلل ويفضل الفردي؛ ويُقاس بـ**الأشكال المتضمنة**.","**نموذج دن ودن**: عناصر **بيئية** (الصوت، الإضاءة، الحرارة) و**انفعالية** (الدافعية، المثابرة) و**اجتماعية** و**جسمية** و**نفسية**.","لا أسلوب أفضل مطلقاً: المعلم **ينوع**، ويساعد الطالب على **الوعي بأسلوبه**."],"src":"Witkin (1977)؛ Kagan (1965)؛ Dunn & Dunn"},"ar.l10.motiv":{"k":"الدافعية","t":["Motivation — Basics & Classroom","الدافعية: خصائصها وإجراءاتها"],"body":["الدافعية **حالة داخلية** تحرّك السلوك؛ **الدافع** داخلي و**الحافز** خارجي و**الباعث** هدف يجذب. والإفراط في المكافآت الخارجية **يُضعف** الداخلية (أثر التبرير الزائد)."],"pts":["**خصائص الدافعية**: الغرضية، النشاط، الاستمرار، التنوع، التحسين والتكيف؛ و**وظائفها**: توليد السلوك وتوجيهه وتحديد شدته وديمومته.","**أنواع الدوافع**: **بيولوجية** (جوع، عطش) و**اجتماعية** مكتسبة (الأمن، الانتماء، الإنجاز)؛ و**موراي** و**أتكنسون** من رواد دافعية الإنجاز.","**نظرية التوقع والقيمة**: الدافعية = توقع النجاح × قيمة المهمة.","إجراءات صفية: تغذية راجعة **فورية وصفية**، توقعات عالية، تنويع، **عدم المقارنة**، إشراك الطالب في مجموعة متميزة، مهام في حدود القدرة مع تحدٍّ."],"ex":[],"src":"Deci & Ryan؛ Eccles & Wigfield؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.3"},"ar.l10.iq":{"k":"الذكاء","t":["IQ & Intelligence Tests","نسبة الذكاء واختباراته"],"body":["**نسبة الذكاء** (ستيرن/تيرمان) متوسطها 100 وانحرافها 15."],"pts":["**جالتون** أكد **الوراثة** وابتكر **معامل الارتباط**؛ **وكسلر** مقاييس لفظية وأدائية؛ **ستانفورد بينيه** أول اختبار مقنن؛ **رافن** مصفوفات غير لفظية."],"src":"Binet & Simon (1905)؛ Terman, Stanford-Binet؛ Wechsler"},"ar.l10.goleman":{"k":"الذكاء","t":["Goleman — Emotional Intelligence","جولمان: الذكاء الوجداني"],"body":["دانيال جولمان رأى أن النجاح لا يتوقف على الذكاء المعرفي وحده، بل على **الذكاء الوجداني (العاطفي)**: فهم الانفعالات وإدارتها في النفس ومع الآخرين."],"pts":["**الوعي بالذات**: معرفة الفرد بانفعالاته.","**تنظيم الانفعالات**: التحكم فيها.","**الدافعية**: توجيه الانفعالات نحو الهدف.","**التعاطف**: فهم مشاعر الآخرين.","**المهارات الاجتماعية**: إدارة العلاقات."],"src":"Goleman, Emotional Intelligence (1995)"},"ar.l10.critical":{"k":"التفكير","t":["Critical, Reflective & Scientific Thinking","التفكير الناقد والتأملي والعلمي"],"body":["**التفكير الناقد**: فحص المعلومات والحجج و**تقويمها** بمعايير مع مراعاة وجهات نظر الآخرين؛ منطلقه **الشك المنهجي**."],"pts":["مهاراته (واطسون–جليسر): **الاستنتاج**، **التعرف على الافتراضات**، **الاستنباط**، **التفسير**، **تقويم الحجج**؛ ومنها **التمييز** بين الحقيقة والرأي والكشف عن **التحيز**.","**التفكير التأملي** مراجعة الخبرة؛ و**اتخاذ القرار** مفاضلة بين بدائل.","**التفكير العلمي** يسير بخطوات حل المشكلات نفسها، وتسمي بعض الأسئلة خطوتيه الأخيرتين «اختبار الفروض» و«الوصول إلى نتيجة قابلة للتحقق»؛ و**الاستدلال** نتيجة من أدلة كافية.","**KWL**: ماذا أعرف؟ ماذا أريد أن أعرف؟ ماذا تعلمت؟ تنمي **ما وراء المعرفة**؛ والدنيا في بلوم: التذكر والفهم والتطبيق."],"src":"Watson & Glaser؛ Dewey, How We Think؛ المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.3"},"ar.l10.creatools":{"k":"الإبداع","t":["Fluency, Flexibility & Idea Tools","أنواع الطلاقة والمرونة وأدوات التوليد"],"pts":["أنواع الطلاقة: **لفظية** (كلمات بحرف معين)، **فكرية/معاني** (حلول كثيرة)، **أشكال**، **تداعي** (كلمات بمعنى واحد).","**المرونة التكيفية** تغيير الوجهة بحسب الموقف، و**المرونة التلقائية** أفكار متنوعة من تلقاء النفس.","**الإثارة العشوائية**: علاقة بين مفهومين لا رابط بينهما («ما العلاقة بين المفتاح والمدير؟»)؛ و**التفكير الجانبي** (ديبونو) خروج من الأنماط المعتادة.","تنمية الإبداع: **أسئلة مفتوحة** («ماذا لو…»، نهاية جديدة لقصة)، **سكامبر**، الرحلة التخيلية، قبول غير المألوف.","**الكلمات المترابطة**: استراتيجية للتفكير الناقد يميز فيها الطالب المترابط من غير المترابط."],"ex":[],"src":"Guilford؛ Torrance؛ Osborn؛ de Bono"},"ar.l10.progs":{"k":"برامج التفكير","t":["Herrmann, 4MAT & Thinking Strategies","هيرمان ومكارثي واستراتيجيات التفكير"],"pts":["**هيرمان – السيطرة الدماغية**: **A** تحليلي منطقي، **B** منظم تخطيطي، **C** عاطفي اجتماعي، **D** تخيّلي كلي.","**مكارثي (4MAT)**: لماذا، ماذا، كيف، ماذا لو؛ و**كولب** دورة التعلم الخبراتي.","**برنامج كورت** ست وحدات: توسعة الإدراك، التنظيم، التفاعل، الإبداع، المعلومات والعواطف، الفعل؛ وأداته **PMI**."],"src":"Herrmann, The Creative Brain؛ McCarthy, 4MAT؛ de Bono, CoRT"},"ar.l10.habits":{"k":"عادات العقل","t":["Costa & Kallick — Habits of Mind","عادات العقل"],"body":[],"pts":["الست عشرة: المثابرة، **التحكم بالتهور**، الإصغاء بتفهم وتعاطف، التفكير بمرونة، **التفكير حول التفكير**، **الكفاح من أجل الدقة**، التساؤل، تطبيق المعارف الماضية، التوصيل بوضوح، جمع البيانات بالحواس، الابتكار، الدهشة، المخاطرة المسؤولة، الدعابة، التفكير التبادلي، التعلم المستمر."],"src":"Costa & Kallick, Habits of Mind"},"ar.l10.attitude":{"k":"الاتجاهات والقيم","t":["Attitudes & Values","الاتجاهات والقيم والتعلم"],"body":["**الاتجاه** استعداد مكتسب ثابت نسبياً للاستجابة بالقبول أو الرفض نحو موضوع، ومكوناته **معرفي** (معتقدات) و**وجداني** (مشاعر) و**سلوكي** (ميل للفعل)."],"pts":["الاتجاه **الإيجابي** يرفع الانتباه والمثابرة، و**السلبي** يخفض الجهد ويصير نبوءة تحقق ذاتها.","تعديله: **خبرات نجاح** مبكرة، ربط المادة **بحياة الطالب وقيمه**، **القدوة**، بيئة لا تسخر من الخطأ، التعزيز، الحوار؛ لا الوعظ وحده ولا الإجبار."],"src":"المعايير التربوية العامة (هيئة تقويم التعليم والتدريب)، المعيار 5.3"},"ar.l11.other":{"k":"مداخل التدريس","t":["Teaching Models, Roles & Other Approaches","عائلات النماذج وأدوار المعلم ومداخل أخرى"],"body":["**مهارة التدريس** أداء جزئي محدد كالتهيئة أو طرح الأسئلة أو الغلق."],"pts":["عائلات **جويس وويل**: **معالجة المعلومات** (الاستقراء، المنظم المتقدم، الاستقصاء، تكوين المفاهيم)، و**الاجتماعية** (التعاوني، لعب الأدوار، التقصي الجماعي).","و**السلوكية** (التعليم المبرمج، التعلم للإتقان، التعليم المباشر)، و**الشخصية** (التدريس غير الموجه).","مداخل أخرى: **التاريخي** (تطور الفكر عبر العصور)، **النشاط** (ديوي)، **الضبط** (التحكم في السلوك)، **التكنولوجي**، **التكاملي** (ربط المادة بغيرها)، **البيئي**، **الديني**.","في المدخل المعرفي: **مدخل المادة الدراسية** يهتم بالمحتوى والكتاب المدرسي، و**مدخل بنية العلم** بمفاهيم العلم الكبرى وطرق بحثه."],"traps":["التدريس غير الموجه من العائلة **الشخصية**، والتعاوني من **الاجتماعية**."]},"ar.l11.lecture":{"k":"طرق العرض","t":["Lecture, Discussion & Dialogue","المحاضرة والمناقشة والحوار والقصة"],"body":[],"pts":["**المحاضرة (الإلقاء)**: تهمل الفروق الفردية.","**المناقشة**: حوار موجه بين المعلم والطلاب أو بين الطلاب؛ مراحلها تهيئة ← مناقشة ← تقويم.","**القصة**: تقدم القيم بأقل تجريد وتنمي الخيال."],"traps":[]},"ar.l11.demo":{"k":"طرق العرض","t":["Demonstration","العرض العملي (البيان)"],"body":[],"pts":["قصوره: الطالب **مشاهد** إن لم يُشرك، وقد لا يرى البعيدون التفاصيل.","العلاج: إشراك الطلاب في التوقع والملاحظة والتسجيل، والعرض المكبر."],"traps":[]},"ar.l11.self":{"k":"التعلم الذاتي","t":["Self-directed & Individualized Learning","التعلم الذاتي وأدواته"],"body":[],"pts":["**الموديول (الوحدة النسقية)**: وحدة صغيرة مستقلة من برنامج أكبر يدرسها الطالب ذاتياً ويُقوَّم بعدها.","أهداف **التعليم الفردي**: مراعاة الفروق، والتعلم للإتقان، والتعلم الموجه، وتنمية الاستقلالية والإبداع؛ ومن **وسائل التعلم الذاتي**: المبرمج، والحقائب والموديولات، والحاسوب، وعقود التعلم.","**البرمجيات التعليمية**: تعليمية (تقديم مفهوم)، و**تدريب وممارسة**، و**محاكاة** (التجارب الخطرة)، و**ألعاب تعليمية**، وحل مشكلات، واستقصاء."],"traps":[]},"ar.l11.social":{"k":"الاستراتيجيات الاجتماعية","t":["Brainstorming, Peers & Other Social Strategies","العصف الذهني والأقران واستراتيجيات اجتماعية أخرى"],"body":[],"pts":["رواد التعلم التعاوني: ديوي و**باركر** و**دويتش** وجونسون وجونسون؛ ومراحله: **التعرف** ← تحديد المهمة ← **الإنتاجية** ← **الإنهاء**.","أنواع **تدريس الأقران**: داخل الفصل، وعبر الصفوف (أعلى يعلّم أدنى)، وأقران المجموعة، وخارج الفصل للمنقطعين؛ والقرين المعلّم يرسخ فهمه.","**الكرسي الساخن**: أسئلة تُطرح على طالب معين لتنمية بناء الأسئلة وتبادل الأفكار؛ و**المائدة المستديرة**: إجابات بالتناوب داخل المجموعة.","**الألعاب التعليمية** نشاط موجه يتنافس فيه الطلاب بمتعة لتحقيق هدف الدرس؛ و**اللعب الموجه** يحدده المعلم و**غير الموجه** حر."],"traps":[]},"ar.l11.dale":{"k":"الوسائل والخبرة","t":["Cone of Experience — Edgar Dale","مخروط الخبرة (إدجار ديل)"],"body":[],"pts":["1) **الخبرات المباشرة الهادفة** (يعمل الطالب بنفسه: زراعة، تجربة حقيقية) 2) **الخبرات المعدلة** (النماذج والمجسمات والعينات) 3) **الخبرات الممثلة** (الدراما ولعب الأدوار).","4) التوضيحات العملية 5) الرحلات الميدانية 6) المعارض 7) التلفاز والأفلام 8) الصور الثابتة والتسجيلات.","9) **الرموز البصرية** (الخرائط والرسوم البيانية) 10) **الرموز اللفظية** (الكلمات المسموعة والمقروءة) وهي الأكثر تجريداً."],"traps":[]},"ar.l12.levels":{"k":"الأهداف","t":["Levels of Objectives","مستويات الأهداف ومصادرها"],"body":[],"pts":["تُشتق الأهداف التربوية العامة من **فلسفة المجتمع** وحاجاته، وطبيعة المتعلم، وطبيعة المعرفة، ونتائج البحوث."],"ex":["الهدف العام «تدريب التلاميذ على أداء العبادات» يُشتق منه الهدف الخاص «أن يؤدي الطالب الوضوء بصورة صحيحة»."],"traps":[]},"ar.l12.plan":{"k":"خطة الدرس","t":["Planning Levels & Lesson Plan","التخطيط ومستوياته وعناصر خطة الدرس"],"body":[],"pts":["أهميته: يوجه التنفيذ، ويضمن تحقيق الأهداف، ويحدد الزمن والوسائل، ويجنب العشوائية؛ وهو أساس **إدارة وقت الحصة**.","عناصر الخطة اليومية: الموضوع، **الأهداف**، المتطلبات السابقة، **التهيئة**، المحتوى والإجراءات، الاستراتيجيات، الوسائل، الأنشطة، **التقويم**، الغلق، الواجب، الزمن.","المهارات المعقدة تُخطط للتدرب عليها **مجزأة** ثم تُجمع، والتخطيط يراعي **الفروق الفردية** ومستوى التجريد لدى الطلاب."],"traps":[]},"ar.l12.content":{"k":"التخطيط","t":["Content Analysis & Knowledge Pyramid","تحليل المحتوى وهرم المعرفة"],"body":[],"pts":["«الماء يغلي عند 100 درجة» **حقيقة**؛ «الضغط» **مفهوم**؛ «كلما زاد الضغط ارتفعت درجة الغليان» **تعميم**.","الانتقال من قاعدة الهرم إلى قمته **استقراء**، ومن الجزء إلى الكل."],"traps":["العلاقة بين مفهومين («كلما… ارتفع…») **تعميم** لا مفهوم."]},"ar.l12.align":{"k":"المعايير ونواتج التعلم","t":["Standards, Outcomes & Alignment","معايير المنهج ونواتج التعلم والمحاذاة"],"body":[],"pts":["بنية المعايير: **البنية التخصصية** للمجال (البعد الرئيس)، ويدعمها **بعد المهارات** و**بعد القيم**.","مؤشر 10.1: يشتق من معايير المناهج أهداف تعلم وفق التصنيف المناسب والأبعاد المشتركة.","التسلسل المنطقي يراعي **المتطلبات السابقة**، ومن البسيط إلى المركب، ومن المحسوس إلى المجرد، وبنية المادة؛ فلا يُقدَّم ناتج يعتمد على مهارة لم تُدرَّس."],"traps":[]},"ar.l12.resources":{"k":"مصادر التعلم","t":["Selecting Learning Resources","شروط اختيار مصادر التعلم الرقمية وغير الرقمية"],"body":[],"pts":["الشروط: **الارتباط بالهدف** أولاً ← **المناسبة لخصائص المتعلمين** ← **الدقة العلمية والحداثة** ← **الوضوح وجودة الإخراج** ← **التوافق مع القيم والثقافة**.","ثم **الأمان** ← **تكلفة ووقت وجهد** يتناسب مع ما يحققه ← **الإتاحة وسهولة الوصول للجميع** بمن فيهم ذوو الإعاقة ← **احترام الملكية الفكرية**.","المصدر الرقمي يُقوَّم أيضاً بموثوقية الجهة الناشرة، وتاريخ التحديث، وخلوه من الإعلانات والمحتوى غير المناسب، وعمله على أجهزة المدرسة وشبكتها.","**التنوع** (مطبوع، مجسم، فيديو، محاكاة، منصة رقمية، بيئة محلية) يراعي أنماط المتعلمين، دون تكديس مصادر كثيرة تشتت الانتباه."],"traps":[]},"ar.l13.active":{"k":"التعلم النشط","t":["Interactive Classroom Strategies","استراتيجيات صفية تفاعلية"],"body":["مبادئ التعلم النشط: مشاركة فاعلة، وربط بالواقع، وتعاون، وتفكير عليا، وتغذية راجعة، ومراعاة الفروق، وتحمل الطالب مسؤولية تعلمه. وهذه استراتيجيات قصيرة تطبقها."],"pts":["**الرؤوس المرقمة**: يُرقَّم أعضاء كل مجموعة ويُستدعى رقم عشوائي ليجيب عنها فيستعد الجميع؛ و**الأعواد** (أعواد الآيسكريم) سحب اسم طالب عشوائياً.","**الكرسي الساخن**: أسئلة لطالب معين لتنمية بناء الأسئلة؛ و**شبكة الأسئلة**: جمع أسئلة الطلاب نهاية الحصة ومناقشتها لتصحيح المفاهيم البديلة."],"traps":[]},"ar.l13.models":{"k":"النماذج البنائية","t":["Constructivist & Metacognitive Models","نماذج بنائية وما وراء معرفية"],"body":[],"pts":["**التعلم المنظم ذاتياً**: الطالب يخطط ويراقب ويقوّم تعلمه.","**نموذج التعلم البنائي الاجتماعي**: تمهيد ← اكتشاف ثنائي ← أنشطة تعاونية ← إتاحة الفرص ← **تقويم ذاتي**؛ يبدأ ثنائياً وينتهي فردياً بخلاف فكر‑زاوج‑شارك.","**نموذج بوسنر للتغير المفاهيمي** يعالج **التصورات البديلة (الخاطئة)**، والتغير نوعان: **تطوري** للخطأ البسيط، و**ثوري** حين يُستبدل المفهوم كله."],"traps":[]},"ar.l13.maps":{"k":"الخرائط","t":["Concept Maps vs Mind Maps","خريطة المفاهيم والخريطة الذهنية وأشكال فن"],"body":[],"pts":["الذهنية: كلمات الربط لا تُشترط غالباً، وأساسها التفكير البصري والتذكر، وأنسب استخدام لها العصف والتلخيص.","المفاهيم: أنسب استخدام لها كشف العلاقات وتقويم الفهم.","**أشكال فن**: للمقارنة بين مفهومين؛ أوجه الشبه في التقاطع والاختلاف في الجانبين."],"traps":[]},"ar.l13.platforms":{"k":"التقنية في التعليم","t":["Ministry Platforms","منصات الوزارة وأنظمة إدارة التعلم"],"body":["**نظام إدارة التعلم** منصة بدروس مسجلة وواجبات وتواصل يدخلها الطالب بحساب وكلمة مرور. ولكل منصة رسمية وظيفة تميزها في الأسئلة."],"pts":["**مدرستي**: المنصة الرسمية للتعليم الإلكتروني منذ 1442هـ؛ فصول افتراضية عبر تيمز، وواجبات واختبارات إلكترونية، وإثراءات.","**عين**: بوابة التعليم الوطنية بدروس ومحتوى رقمي للمناهج وقنوات عين الفضائية.","**روافد**: مستودع المصادر الرقمية؛ و**منظومة التعليم الموحد**: منصة التعلم عن بعد التي سبقت مدرستي."],"traps":[]},"ar.l13.mayer":{"k":"الوسائط المتعددة","t":["Mayer's Multimedia Principles","مبادئ ماير للوسائط المتعددة"],"body":["مبادئ لتصميم العروض والفيديو التعليمي تخفف العبء على ذاكرة المتعلم."],"pts":["التقارب **المكاني** (النص قرب الصورة) و**الزماني** (الصوت مع الصورة في الوقت نفسه).","**الاتساق**: حذف المشتتات والزخارف غير اللازمة.","**الصيغة**: تعليق صوتي مع الرسوم أفضل من نص مكتوب.","**التكرار الزائد**: لا يُعرض نص مكتوب مطابق للصوت نفسه.","**التجزئة**: تقسيم العرض إلى أجزاء يتحكم المتعلم في تتابعها؛ و**الشخصنة**: أسلوب حواري قريب."],"traps":["قراءة الشرائح نصاً بالصوت نفسه تخالف مبدأ **التكرار الزائد**."]},"ar.l13.tools":{"k":"التقنية في التعليم","t":["Web Tools, Apps & Digital Citizenship","أدوات الويب والتطبيقات والمواطنة الرقمية"],"body":["من مميزات الحاسب في التعليم: السرعة الذاتية، والاعتماد على النفس، والجمع بين الترفيه والتعليم."],"pts":["**الرحلات المعرفية (ويب كويست)**: بحث جماعي في **مصادر يحددها المعلم مسبقاً**؛ بنيتها مقدمة، مهمة، عملية، مصادر، تقويم، خاتمة.","**المدونة** للنشر والتعليق، و**الويكي** يحررها عدة مستخدمين، و**البودكاست** صوتي، و**الفيديو التفاعلي** للتعلم الفردي، و**الواقع المعزز** يضيف عناصر رقمية إلى الواقع.","**إكسل** للجداول والرسوم والإحصاء البسيط وبرنامج **SPSS** للتحليل الإحصائي، و**أكسس** لقواعد البيانات، و**كانفا** للتصميم، و**بوبلت** للخرائط المعرفية، و**كاهوت** للألعاب التفاعلية.","**المواطنة الرقمية** (**الثقافة الرقمية**): قواعد توجه نحو منافع التقنية والحماية من أخطارها، والاستخدام الآمن والأخلاقي وتقويم مصداقية المصادر.","معايير **ISTE** دولية لتوظيف التقنية (للطلاب والمعلمين والقادة)، و**الذكاء الاصطناعي** للتعلم التكيفي والتغذية الراجعة الآلية مع تحقق المعلم من دقته."],"traps":[]},"ar.l13.currorg":{"k":"المنهج","t":["Curriculum Organization & Design Models","تنظيمات المنهج ونماذج بنائه"],"body":["**المنهج بمفهومه التقليدي** المقرر والكتاب وحفظ المعلومات وإهمال الفروق، و**بمفهومه الحديث** جميع الخبرات التي تهيئها المدرسة داخلها وخارجها وتراعي المتعلم. و**المقرر** موضوعات مادة معينة، و**الكتاب المدرسي** وعاء المحتوى والوسائل والأنشطة، و**المحتوى** المعارف والمفاهيم والمهارات والقيم."],"pts":["التنظيمات: **المواد المنفصلة**، **المترابطة** (تنسيق بين مادتين مع بقائهما)، **المندمجة** (الاجتماعيات)، **المجالات الواسعة** (العلوم العامة)، **المحوري** (محور مشترك ومواد اختيارية).","و**النشاط** (ديوي: ميول الطلاب وحل المشكلات)، و**الوحدات**، و**الحلزوني** (برونر: المفاهيم تعود بتعمق)، و**المنهج التكنولوجي** (تقنية تنظم الخبرات ويعتمد على **الخطو الذاتي**).","**نموذج تابا** استقرائي يبدأ **من المعلم**: تشخيص حاجات الطلاب ← صياغة الأهداف ← اختيار المحتوى وتنظيمه ← الخبرات ← التقويم.","**المنهج كنظام**: **مدخلات** (أهداف ومحتوى) ← **عمليات** (طرق وأنشطة ووسائل) ← **مخرجات** (نواتج التعلم) ← **تغذية راجعة** (تقويم)."],"traps":[]},"ar.l14.styles":{"k":"إدارة الصف","t":["Management Styles, Rules & Time","أنماط الإدارة والقواعد الصفية وإدارة الوقت"],"body":[],"pts":["**اشرح للطلاب فوائدها** واتفق عليها معهم حتى يطبقوها **ذاتياً**؛ فالانضباط (تنظيم ذاتي) أعلى من النظام (مصدره خارجي)، وهذه **الإدارة الذاتية للصف**.","**الوقت الأكاديمي**: إجراءات روتينية لبدء الحصة وإنهائها، و**انتقالات** سلسة، وتهيئة قصيرة؛ تقل المشكلات حين **ينهمك الطلاب في النجاح**.","المجموعات: 4–6 أعضاء بأدوار (قائد، مقرر، ضابط وقت، متحدث)، مسؤولية فردية مع اعتماد إيجابي متبادل؛ والمعلم **ميسّر** ومرشد لا ملقّن ولا متفرج."],"traps":[]},"ar.l14.othermod":{"k":"تعديل السلوك","t":["Other Behavior-Change Techniques","أساليب أخرى في تعديل السلوك"],"body":[],"pts":["**التحصين التدريجي** للخجول خطوة خطوة مقابل **الغمر** دفعة واحدة؛ و**الكف المتبادل**: إحلال عادة مقبولة محل أخرى؛ و**الإشباع**: تقديم المثير بكميات كبيرة حتى يفقد جاذبيته.","**ضبط الذات** (تقييد النفس كالحمية)، و**السلوك التوكيدي** (تعليمات تبني ثقة الطالب بنفسه)، و**الإرشاد بالواقع** (توظيف القراءة والأنشطة الواقعية)؛ و**العقد السلوكي** اتفاق مكتوب بالسلوك والمكافأة.","**النشاط التعزيزي** نشاط إضافي لمن أتقن لتثبيت التعلم وتعميقه، و**النشاط العلاجي** لمن لم يتقن."],"traps":[]},"ar.l14.cases":{"k":"بيئة آمنة","t":["Handling Student Cases","التعامل مع فئات الطلاب والمشكلات السلوكية"],"body":[],"pts":["**المعتدى عليه** (في التنمر): بناء ثقته وتعليمه مهارات اجتماعية وضمان حمايته؛ لا لومه ولا مواجهته مع المتنمر أمام الصف، ولا يُعالج التنمر بطلب النقل أو التجاهل.","**الخجول**: علاقة ثقة أولاً، ثم مهام سهلة ناجحة، وتواصل **غير لفظي** مشجع، وتحصين تدريجي؛ والخطأ **تجنب سؤاله** أو الزج به أمام الجميع أو تحويله فوراً للموجه الطلابي.","**كثير الحركة**: مقعد قريب من المعلم، ومهام فيها حركة مشروعة، وأنشطة قصيرة متنوعة؛ لا حرمانه من الحركة كلياً ولا من الفسحة.","**المشاغب أو المتحدي**: لقاء فردي بود وحزم لفهم السبب، لا مواجهة علنية، ثم اتفاق سلوكي وعواقب ثابتة؛ و**المحبط قليل الدافعية**: استكشف سبب إحجامه، ثم مهام متدرجة ونجاح مبكر وتعزيز الجهد."],"traps":[]},"ar.l14.comm":{"k":"التواصل","t":["Classroom Communication","الاتصال الصفي ولغاته ومعوقاته"],"body":[],"pts":["أنماطه: **وحيد الاتجاه** (محاضرة)، **ثنائي** (معلم وطالب)، **متعدد/مفتوح** (تفاعل الجميع بتوجيه المعلم) وهو الأفضل.","الأسئلة الصفية: **مغلقة** (إجابة واحدة)، **مفتوحة** (تفكير متباعد)، **سابرة** (تبني على إجابة الطالب)، **تجميعية** (تجمع عدة أفكار).","معوقات التفاعل و**معوقات الاتصال**: **خوف الطلاب من الخطأ**، والتعزيز غير المناسب، ومقاطعة المعلم، والتوقعات المنخفضة، وشرود الذهن، والضجيج، وغموض الرسالة؛ والعلاج تنويع المثيرات والأسئلة.","وظائف التغذية الراجعة: **تعزيزية**، و**إخبارية**، و**دافعية**، وتقويمية."],"traps":[]},"ar.l14.ethics":{"k":"القدوة والعلاقة المهنية","t":["Role Model & Professional Boundaries","القدوة وحدود العلاقة المهنية والتراجع عن الخطأ"],"body":[],"pts":["دوره في قواعد 1447: **تمثيل القدوة الحسنة للسلوك الإيجابي في القول والفعل**، وتعزيز الانضباط الذاتي، وتوضيح القواعد، وتعديل السلوك بالاستفادة من التوجيه الطلابي.","ومن دوره: توثيق مشكلات الانضباط في سجلات خاصة، و**رصد الحضور في كل حصة**، و**تمكين الطالب من فرص التعويض**، وطلب المشورة من لجنة التوجيه الطلابي.","**يرصد المعلم مشكلات الدرجة الثانية فأعلى** التي باشرها ويسلم الأسماء للإدارة، ومثالها الدخول أو الخروج من الفصل دون استئذان؛ أما التأخر في دخول الحصة والنوم في الفصل فمن الدرجة الأولى."],"traps":[],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام (الإصدار الخامس 1447هـ)؛ المعايير التربوية العامة."},"ar.l14.safety":{"k":"الأمن والسلامة","t":["Classroom Safety & Emergencies","السلامة في الصف والمختبر والطوارئ"],"body":[],"pts":["**الجاهزية** و**إتاحة الوصول للجميع**: عدد كافٍ من الأدوات أو **تناوب عادل**؛ وموقع يرى منه الجميع، وخط مكبر لضعيف البصر، ونص مرافق للفيديو لضعيف السمع، وممرات خالية للكرسي المتحرك، وبدائل لمن لا يملك جهازاً.","**السلامة في الصف**: ممرات واسعة، ومخارج غير مسدودة، وأثاث ثابت، وتوصيلات آمنة، وتهوية وإضاءة مناسبتان، وأدوات خطرة محفوظة.","**المختبر**: تعليمات قبل التجربة، و**نظارات وقفازات واقية**، ولا أكل ولا شرب ولا تذوق ولا شم مباشر، ومواد **موسومة**، ومعرفة مكان **طفاية الحريق** و**حقيبة الإسعافات الأولية**، و**إشراف دائم**.","**محاولة إيذاء الذات** (المادة 30): الهدوء وأخذ كلامه بجدية، وتجنب كثرة الأسئلة، ومكان آمن و**عدم تركه بمفرده**، وحفظ خصوصيته، والتبليغ فوراً (إدارة التعليم، الجهات الأمنية، الحماية من العنف الأسري وحماية الطفل 1919، وزارة الصحة)."],"traps":[],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام (الإصدار الخامس 1447هـ)؛ المعايير التربوية العامة."},"ar.l15.eval":{"k":"مفاهيم التقويم","t":["Educational Evaluation: Qualities & Functions","التقويم التربوي: خصائصه ووظائفه"],"body":["التقويم التربوي يشمل تقويم المتعلم والمعلم والمنهج والإدارة والمبنى، والتقويم التعليمي جزء إجرائي منه."],"pts":["**مواصفات الاختبار الجيد**: الصدق، الثبات، الموضوعية، **التمييز**، **الشمول** (تغطية المحتوى وفق جدول المواصفات)، والتقنين، وسهولة التطبيق والتصحيح.","**وظائف التقويم**: تشخيص الضعف، وتوجيه التعلم، والحكم على الأهداف، وتطوير المناهج وطرق التدريس، ودعم القرارات الإدارية."],"traps":[]},"ar.l15.tools":{"k":"أدوات التقويم","t":["Other Assessment Tools","أدوات تقويم أخرى: السجلات والملاحظة والمقابلة والتقارير الذاتية"],"body":["كل أداة تكشف جانباً لا يكشفه الاختبار الورقي؛ فاختر الأداة بحسب ما تريد قياسه."],"pts":["**السجل القصصي**: وصف دقيق مؤرخ لسلوك طالب في موقف محدد كما حدث؛ من عيوبه الوقت الطويل وتأثره بذاتية الملاحِظ. و**سجل سير التعلم (اليوميات)** يكتب فيه الطالب تأملاته.","**الملاحظة** أنسب لتقويم المهارات العملية والسلوك، بسيطة أو منظمة بأداة (بطاقة ملاحظة)؛ و**المقابلة / المؤتمر** تواصل وجهاً لوجه حول أعمال الطالب وتفكيره.","**تقويم الأقران** يعتمد على نشاطين رئيسيين: **الملاحظة** و**التواصل**، وهو مكمل للتقويم الذاتي.","**التقارير الذاتية** للنواتج **الوجدانية**: مقاييس **الاتجاهات** (ليكرت الخماسي)، ومقاييس **الميول** (سترونج وكودر)، والاختبارات الإسقاطية، والمقابلة المقيدة أو المفتوحة.","**الاختبارات الشفوية**: أنسب للصفوف الأولية ومواد كالقرآن الكريم، ينعدم فيها الغش وتكشف التعبير، لكنها تستغرق وقتاً وتتأثر بذاتية المعلم وخوف الطالب."],"traps":[]},"ar.l15.intl":{"k":"الاختبارات الوطنية والدولية","t":["National & International Assessments","نافس والاختبارات الدولية"],"body":["**نافس** الاختبارات الوطنية التي تنفذها هيئة تقويم التعليم والتدريب لقياس مخرجات التعلم في القراءة والرياضيات والعلوم للصفوف 3 و 6 و 9؛ غرضها تشخيص المستوى الوطني وتحسين التعليم لا ترتيب الطالب أو نجاحه."],"pts":["**PISA** (بيزا) من منظمة OECD، لعمر 15 سنة، كل 3 سنوات، يقيس تطبيق المعرفة في القراءة والرياضيات والعلوم في مواقف حياتية.","**TIMSS** (تيمس) من IEA، للصفين الرابع والثامن (الثاني متوسط)، كل 4 سنوات، في الرياضيات والعلوم."],"traps":["اختبار PISA بالعمر (15 سنة)، أما (TIMSS, PIRLS) ف**بالصف**."]},"ar.l15.access":{"k":"تقويم ذوي الإعاقة","t":["Test Accommodations","تسهيلات الاختبار وتقويم الطلاب ذوي الإعاقة"],"body":[],"pts":["**البصرية**: برايل، أو الشفهي، أو التسجيل الصوتي، أو **قارئ كاتب مبصر**، و**الطباعة المكبرة والعدسات** لضعاف البصر، وتكييف الصور والرسوم أو بديل لها.","**السمعية**: أسئلة **موضوعية مباشرة واضحة** بدل المقالية والمركبة، وترجمة بلغة الإشارة، و**عدم محاسبة الأصم على الأخطاء الإملائية والنحوية**، واستبدال مهارات الاستماع بنصوص أو صور.","**صعوبات التعلم**: قراءة الأسئلة بصوت عال، والإجابة **شفهياً** أو كتابتها عنه أو تسجيلها، و**فترات راحة**، وتقويم فردي بعيد عن المشتتات؛ و**فرط الحركة**: **فترات قصيرة**، والسماح **بالتوقف والتحرك**، والاختبار في **ركن خاص بعيد عن المشتتات**.","**الجسمية**: الأجهزة التعويضية، وإجابة شفهية يكتبها أحد منسوبي المدرسة الموثوقين بتكليف من المدير، وإعفاء من التقويمات العملية والرسم الكتابي؛ و**اضطرابات النطق**: لا يُحاسب على أخطائها، ويمكن استبدال الشفهي بالتحريري."],"ex":[],"traps":[],"src":"لائحة تقويم الطالب 2025 وإجراءاتها التنفيذية؛ المعايير التربوية العامة (مؤشر 10.2)."},"ar.l16.records":{"k":"سجلات الرصد","t":["Record-keeping & Data Analysis","سجلات الرصد وتحليل النتائج ببرامج الجداول"],"body":[],"pts":["نموذج الرصد الجيد: صف لكل طالب، وأعمدة **بالمعايير أو نواتج التعلم** والأداة والتاريخ، ومستوى الإتقان أو الدرجة، وعمود للملحوظات والإجراء العلاجي؛ و**الرصد التراكمي** يُظهر **مسار تقدم** الطالب (قبلي ← تكويني ← ختامي).","**المؤشرات الأساسية للأداء**: نسبة الإتقان في كل معيار، وتوزيع الطلاب على المستويات، وأضعف المعايير وأقواها، والطلاب المحتاجون لعلاج أو إثراء، وتطور الأداء عبر الفترات.","اللائحة: **يحلل المعلم نتائج طلابه** لتحديد مواطن القوة والضعف وأسبابها وبناء خطة علاجية، وتحلل **لجنة التحصيل الدراسي** النتائج على مستوى المدرسة.","حساب النسبة المئوية لتحصيل الصف يحتاج عدد الطلاب ودرجاتهم والدرجة الكلية، ولا يحتاج عدد الفصول."],"ex":[],"traps":[],"src":"لائحة تقويم الطالب 2025 وإجراءاتها التنفيذية؛ المعايير التربوية العامة (مؤشر 10.3)."},"ar.l01.identity":{"k":"الهوية الوطنية","t":["Vision 2030 & National Identity","رؤية 2030 وتعزيز الهوية الوطنية"],"aka":["برنامج تنمية القدرات البشرية","رؤية 2030"],"body":["الهوية الوطنية تُبنى بشواهد يراها الطالب: خدمة الحرمين، ومنجزات رؤية 2030، والمشاريع الوطنية، لا بالوعظ المجرد. ومن واجبات المعلم في الميثاق أنه **أمين على كيان الوطن ووحدته**، يعمل لتسود المحبة بين المواطنين وبينهم وبين ولاة الأمر."],"pts":[],"traps":[],"src":"رؤية المملكة 2030 (برنامج تنمية القدرات البشرية)؛ ميثاق أخلاقيات مهنة التعليم 1427هـ"},"ar.l01.heritage":{"k":"مؤشر 1.2","t":["National Heritage in the Lesson","التراث الوطني والمناسبات في الدرس"],"aka":["التراث المادي","التراث غير المادي"],"body":[],"pts":["**التوظيف داخل المادة**: مسألة رياضية عن مساحة مبنى تراثي، نص قرائي عن الضيافة، مشروع عن حرفة من منطقة الطالب، مقابلة كبار السن، زيارة متحف أو موقع تراثي.","**المناسبات**: يوم التأسيس (22 فبراير) ذكرى تأسيس الدولة السعودية الأولى على يد الإمام محمد بن سعود عام 1139هـ (1727م)؛ اليوم الوطني (23 سبتمبر) ذكرى توحيد المملكة على يد الملك عبدالعزيز عام 1351هـ (1932م)؛ يوم العلم (11 مارس)."],"traps":["يوم التأسيس = الدولة السعودية **الأولى** (1139هـ)؛ اليوم الوطني = **توحيد المملكة** (1351هـ)."],"src":"المعايير المهنية للمعلمين، هيئة تقويم التعليم والتدريب (1.2)؛ قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ (السلوك المتميز)"},"ar.l02.policy":{"k":"وثيقة 1390","t":["Education Policy Document (1390 AH)","وثيقة سياسة التعليم 1390هـ"],"aka":["سياسة التعليم","الأسس العامة","مصادر الأهداف"],"body":[],"pts":["**مصادر الأهداف**: العقيدة الإسلامية، الأوضاع الاجتماعية والاقتصادية ومطالب التنمية، اتجاهات العصر، حاجات المواطن.","**من مبادئها**: التربية المتكاملة (إعداد المواطن المؤمن إعداداً سليماً متوازناً)، طلب العلم فريضة، حق الفتاة في التعليم، توجيه العلوم توجيهاً إسلامياً.","**المراحل**: ابتدائي 6 سنوات، متوسط 3، ثانوي 3 (السلم 12 صفاً)؛ ولذوي الاحتياجات الخاصة توضع **سياسة شاملة لرعايتهم**؛ وتأسست وزارة المعارف عام **1373هـ**، والتعليم حق لكل مواطن تكفله الدولة.","**سن القبول** في الصف الأول: من أكمل **ست سنوات** عند بداية العام الدراسي (إعلان 1448: حتى 24 أغسطس 2020م)، ومن يصغر بنحو 90 يوماً يُقبل **بشرط إتمام سنة في رياض الأطفال** (القواعد القديمة كانت تحسبها هجرية)؛ وهذه من **قواعد القبول** في الوزارة لا من نص الوثيقة، وفي النظام الجديد يحدد سنَّ القبول المجلس (المادة 8)."],"traps":[],"src":"سياسة التعليم في المملكة العربية السعودية (قرار مجلس الوزراء 779 وتاريخ 1389/9/16هـ)؛ قواعد القبول في وزارة التعليم؛ قرار مجلس الوزراء 103 (1448هـ)"},"ar.l02.jobsmore":{"k":"لائحة","t":["Education Jobs Regulation: Details","لائحة الوظائف: الترقية والأداء والإجازات"],"aka":["الأنشطة اللاصفية","الفاقد التعليمي","إجازات المعلم"],"body":["تفاصيل من لائحة الوظائف التعليمية تتكرر في الأسئلة بعد الرتب والرخصة."],"pts":["**الترقية**: رخصة سارية بالمستوى المطلوب + تقويم أداء **جيد جداً فأعلى** آخر ثلاث سنوات + إكمال سنوات الرتبة (6 بكالوريوس / 5 ماجستير / 4 دكتوراه).","**الأنشطة اللاصفية**: الحصص غير التدريسية كالتخطيط والتقويم وإدارة الأنشطة والمشاركة في التطوير المهني والأعمال الإدارية.","**إجازات المعلم**: الصيفية مع نهاية العام الدراسي، والمرضية والاضطرارية بضوابط نظام الخدمة المدنية؛ و**الاضطرارية** لا تتجاوز خمسة أيام في السنة ولا تُخصم من الصيفية.","**تعديل 1446**: الرخصة إلزامية لمزاولة التعليم اعتباراً من فبراير 2026 مع إعفاء من بلغ الخمسين قبله، وأُلغي ربط العلاوة بالرخصة."],"traps":[],"src":"لائحة الوظائف التعليمية بتعديلات 1446هـ (المادة 9/4)؛ اللائحة التنفيذية للموارد البشرية في الخدمة المدنية (المادة 123: التظلم من نتيجة تقويم الأداء)"},"ar.l02.grades":{"k":"قواعد 1447","t":["Behavior & Attendance Grades","درجات السلوك والمواظبة في قواعد 1447"],"aka":["درجة السلوك","درجات الحسم","المواظبة"],"body":[],"pts":["**الحسم** حسب درجة المشكلة: 1، 2، 3، 10، 15؛ وللطالب **فرص تعويض** للمحسوم بممارسات السلوك المتميز، والتعويض **لا يعفيه** من بقية الإجراءات.","**الضمانات**: **مناسبة الإجراء للمرحلة العمرية** والظروف، و**سرية** معلومات الطالب المخالف، وتزويده **بنوع المشكلات** التي حُسمت بسببها درجاته إذا طلب.","**المواظبة** من الثالث الابتدائي إلى الثالث الثانوي (وتقدير كيفي في الصفين الأول والثاني): تُحسم **درجة واحدة عن كل يوم غياب بدون عذر**؛ والعذر المقبول في وقته لا يؤثر فيها.","**تجاوز الغياب بدون عذر 10%** من أيام العام يحرم الطالب من الانتقال: الابتدائية والمتوسطة إلى العام التالي، والثانوية إلى الفصل التالي.","تكرار الغياب بدون عذر: تحويل إلى **الموجه الطلابي** ← إحالة إلى **لجنة التوجيه الطلابي** ← مخاطبة **الجهات المختصة** وفق نظامي حماية الطفل والحماية من الإيذاء، مع استمرار الخدمات التعليمية واستكمال الغائب خطة التعلم بعذر أو بدونه."],"traps":[],"src":"قواعد السلوك والمواظبة لطلبة التعليم العام، الإصدار الخامس 1447هـ"},"ar.l04.parenttools":{"k":"أولياء الأمور","t":["Parent Communication Channels","قنوات التواصل مع الأسرة"],"aka":["الخطاب الإداري","تقنيات التواصل"],"body":[],"pts":["تقنيات التواصل تُطلع أولياء الأمور على **خطط المعلم التدريسية وتعلم الطلاب**.","منصة **School Circle**: مشاركة الملفات ومساحة افتراضية للنقاش بين المعلم والطلاب وأولياء الأمور؛ وتطبيق **TeacherApp**: رصد الحضور والغياب والتقييم.","العلاقة الفاعلة تُظهر **الجانب الإيجابي** وتدعو ولي الأمر للفعاليات والتكريم، وولي الأمر المتعاون يُمنح عضوية **مجلس المدرسة**.","**الخطاب الإداري** لمدير المدرسة أو جهة رسمية: عنوان، تحية، موضوع واضح، خاتمة، توقيع؛ لا رسالة ودية ولا شفهية.","الميثاق: المعلم **شريك الوالدين**، ويحفظ **سرية** الاجتماعات، ولا يتحدث عن الطالب أمامه مدحاً أو ذماً."],"src":"مدونة قواعد السلوك الوظيفي وأخلاقيات الوظيفة لشاغلي الوظائف التعليمية، وزارة التعليم، 1447/2/3هـ (المادة 9)؛ ميثاق أخلاقيات مهنة التعليم 1427هـ"}};
